programs.sol:
"""A sparse source-code/package and qualified-name boundary signal.

Positive pulses mark package names and Go header openings. Negative pulses mark
package metadata, dotted fragments and quoted module/URL arguments. Document-initial
code markers, a Title delimiter and repeated middle dots have separate rules.
Coefficients summarize training examples; ordinary lexical variation is omitted.
The bounded text tail and token count reset at document boundaries.
"""
import re

READS = ()

# Reversed internet-domain roots used for Java namespaces.
PACKAGE_ROOTS = {
    'com': 9.15, 'org': 5.76, 'net': 5.68, 'cn': 8.05,
    'ru': 5.73, 'br': 3.74, 'edu': 0.75, 'io': 4.0,
}
IMPORT_ROOTS = {
    'com': 0.44, 'org': 0.65, 'net': 1.57, 'cn': 2.83,
    'ru': 2.52, 'br': 1.65, 'io': 0.85, 'java': -0.21,
}
CODE_START = {
    'package': -0.89, 'import': -0.75, 'def': 3.64,
    '#include': 0.68, '#': 0.40, '#[': 3.0, '#![': 3.0, '--': -2.05,
}
PACKAGE_SUFFIX = {
    'Json': -3.2, 'json': -4.1, '-lock': -3.5,
    'Manager': -2.5, '_id': -2.3, '_json': -2.3,
}
# Software hosts and conventional placeholder/local-host prefixes.
TECHNICAL_HOSTS = {'www', 'github', 'gitlab', 'example', 'localhost'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, tail, position = carry
    s = prefix.token_strings[-1]
    word, prev = s.strip(), previous.strip()
    value = 0.0

    if position == 0:
        value = CODE_START.get(word, 0.0)
        if word == '//' and '\n' in s:
            value = -4.8
        elif word.startswith('"""'):
            value = 2.06
    elif re.search(r'(?:^|[\s/("\'])package$', previous, re.I):
        if word == '.json':
            value = -2.6 if '/' in previous else -4.1
        elif word in PACKAGE_SUFFIX:
            value = PACKAGE_SUFFIX[word]
        elif s.startswith(' ') and word.isidentifier() and word.islower():
            declaration = re.search(r'(?:^|\n|\\n|\t) *package$', tail)
            if position == 1:
                value = PACKAGE_ROOTS.get(word, 4.3)
            elif word in PACKAGE_ROOTS:
                value = 2.7
            elif declaration and word != 'body':
                value = 1.7
    elif prev == 'import':
        line = tail.replace('\\n', '\n').rsplit('\n', 1)[-1]
        from_import = bool(re.search(r'\bfrom\b', line))
        if s.startswith('("') or s.startswith("('"):
            value = -1.2  # JavaScript's quoted dynamic-import path.
        elif s.startswith(' (') or s == ' "':
            if from_import:
                value = 0.3
            elif '\\' in s:
                value = 2.0
            else:
                bare_go_import = previous == 'import' and 'package ' in tail
                value = 6.0 if bare_go_import else 4.0
        elif s.startswith(' ') and word in IMPORT_ROOTS:
            value = IMPORT_ROOTS[word]
        elif s.startswith(' ') and word.isalpha() and word.islower():
            value = 0.0 if from_import else 0.3
    elif prev == 'func' and s.startswith(' ('):
        value = 0.5
    elif prev == 'www' and s.startswith('.') and word[1:].isalpha():
        value = -0.55 if len(word) <= 4 else -0.25
    elif prev in IMPORT_ROOTS and s.startswith('.') and word[1:].islower():
        if prev != 'java':
            value = -0.55 if len(word) <= 4 else -0.1
    elif prev == '://' and s.isalpha() and s not in TECHNICAL_HOSTS:
        value = -0.24
    elif (s.startswith('(\"') or s.startswith("('")) and (
        prev.lstrip("'\"") in ('url', 'library')
    ):
        value = -2.1 if prev.lstrip("'\"") == 'url' else -1.5
    elif position == 1 and prev == 'Title' and s == ':':
        value = 2.55
    elif prev == 'path' and s == '/to':
        value = -1.0
    elif prev == 'module' and s == '.exports':
        value = -1.0

    package_name = re.fullmatch(r'package +[A-Za-z_]\w*', tail)
    if package_name and (s.isidentifier() or s.isalnum()):
        value = 3.0  # A package identifier continued across tokenizer pieces.
    if (position == 2 and tail.startswith('package ')
            and s.startswith('.') and len(s) > 1):
        # Reversed country-code domains can continue as br.com, au.com, etc.
        value = 2.2 if len(prev) == 2 and s == '.com' else -1.0
    header = re.search(r'(?:^|\n|\\n|\t) *package +[A-Za-z_]\w*$', tail)
    if s.startswith('\n') and header:
        value = 5.0 if '\n\n' in s else 3.0
    if len(word) >= 2 and set(word) == {'·'}:
        value = -1.65

    return (doc, s, (tail + s)[-160:], position + 1), float(value)

programs.haiku:
"""Java/Go package and import headers (layers.1.mlp.down_proj:3776).

What it does: this component is a detector for the first name written after the
keyword `package` or `import` at the top of a source file. It writes a large
positive value on the token that starts a reverse-domain package name:
    package com.example...   -> large (the " com" token, about +8 on average)
    package org.foo...       -> about +4.5
    package cn/ru/br/net...  -> about +3
    import org.x / import com.x / import io.x -> small positive (0.5 to 2)
    Go block opener `import (` -> about +4
Other package names after `package` get a small positive value; file-name-like
tokens after `package` (".json", ".h", ".sh", ...), as in "package.json", get a
negative value. Everything else, including the first token of every document,
is predicted as 0. The rest of the activation (most positions) is small,
diffuse and not captured here.
"""

READS = ()

# Web-domain prefixes that begin a reverse-domain package name, e.g. com.x, org.x.
DOMAINS = {"com", "org", "net", "io", "cn", "br", "ru", "dev", "edu"}
# File-name extensions that show up right after `package` in "package.json" text.
FILE_EXTENSIONS = {".json", ".h", ".sh", ".xml", ".go", ".lock", ".js", ".ts", ".py"}


def step(carry, prefix, upstream):
    # A document's first token has no preceding keyword: predict 0.
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    keyword = prefix.token_strings[-2].strip()
    token = prefix.token_strings[-1]
    name = token.strip()
    value = 0.0
    if keyword == "package":
        if name == "com":
            value = 7.5
        elif name == "org":
            value = 4.5
        elif name in DOMAINS:
            value = 3.0
        elif name in FILE_EXTENSIONS:
            value = -5.0
        else:
            value = 0.5
    elif keyword == "import":
        if name in ("com", "org"):
            value = 0.5
        elif name in DOMAINS:
            value = 2.0
        elif token.lstrip().startswith("("):
            value = 4.0
    return None, value

programs.sol:
"""A sparse detector of boilerplate labels and code/document openings.

Negative pulses occur on attribution labels, preview/paywall links, installation
and lint commands, and initial escaped text or comment syntax. A few familiar
formatting sequences have weaker responses. Everything else is approximated by
zero. Most lexical and context-dependent variation remains unexplained.
"""
import re

READS = ()


def response(token, before, opening):
    if opening:
        # Literal escapes and source-file opening conventions.
        escapes = {'\\n': -1.40, '\\t': -1.22, '\\"': -2.15}
        if token in escapes:
            return escapes[token]
        if token == '<|endoftext|>':
            return -2.41
        if token.startswith('/*'):
            if token.count('*') > 5:
                return -0.96
            if token.startswith('/**') and '\n' in token:
                return -1.70
            return -1.35 if '\n' in token else -1.18
        if token.startswith(('"""', "'''")):
            return -1.32
        if token == '<!':
            return -2.47
        if token.startswith('#!'):
            return -0.78
        if token and set(token) == {'#'}:
            return -0.38
        if token == '//':
            return -0.51
        declarations = {'import': -0.94, 'package': -0.69, 'using': -0.57}
        if token in declarations:
            return declarations[token]
        if len(token) >= 4 and set(token) == {'^'}:
            return -1.445
        if len(token) >= 2 and set(token) == {'·'}:
            return -0.738

    # Authorship, sorting, and other metadata labels.
    if token == ' By':
        if re.search(r'/\*\s*$', before) and (
                ':+:' in before or '+:+' in before):
            return -5.1  # Author line in a decorated C source header.
        if re.search(r'\b(?:Asked|Answered|Posted|Reviewed|Sort)$', before):
            return -1.55
        if before.endswith('Reported'):
            return -0.47
    if token == 'By' and before.endswith('Created'):
        return -1.19
    if token == ' by':
        if before.endswith('Uploaded'):
            return -1.56
        if before.endswith('posted'):
            return -0.14
        if '/*' in before and re.search(
                r'(?:Created|Updated):.*\d\d:\d\d:\d\d$', before):
            return -2.0
    if token == ' reply' and before.endswith('Latest'):
        return -0.91
    if token == ' On' and before.endswith('Updated'):
        return -0.99

    # Document-preview and navigation boilerplate; only the prefix is examined.
    lower = before.lower()
    if lower.endswith('this preview shows'):
        if token == ' pages':
            return -1.73
        if token == ' page':
            return -1.07
    if token == ' pages' and lower.endswith('this preview shows document'):
        return -0.45
    if (token == ' document' and lower.endswith('view the full')
            and 'sign up' in lower):
        return -0.78
    if token == ' Document' and lower.endswith('view full'):
        return -2.45 if 'blurred sections' in lower else -0.90
    if token in (' details', ' Details'):
        if re.search(r'\bview(?: full)?$', lower):
            return -0.95
        if lower.endswith('conversion'):
            return -0.97

    # Package installation and source-code lint suppression directives.
    if token == ' install':
        if re.search(r'\bapt(?:-get)?$', before):
            return -0.81
        if re.search(r'\bpip[23]?$', before):
            return -0.26
    if token == '-disable' and before.endswith('eslint'):
        return -2.65 if before == '/* eslint' else -0.90
    if token == ' disable' and before.endswith('pylint:'):
        return -0.90
    if token == ' another':
        if re.search(r'\b[Pp]ut$', before):
            return -0.81
        if re.search(r'\b[Aa]dding$', before):
            return -0.65

    # Recognizable URL, repository-metadata, and formatting fragments.
    if token == 'ars' and before.endswith('<gh_st'):
        return -2.03
    if token == 'adge' and before.endswith('shields.io/b'):
        return -1.22
    if token == '://' and re.search(r'https?$', before):
        return 0.17
    if token == '_modules' and before.endswith('node'):
        return -0.17
    if token in ('s', 'd', 'f') and before.endswith('%'):
        return -0.17
    if token == '年' and before[-1:].isdigit():
        return -0.18
    return 0.0


def step(carry, prefix, upstream):
    token, document = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, first, opening = '', token, True
    else:
        _, before, first, opening = carry
        opening = opening and token == first
    value = response(token, before, opening)
    # Equal tokens repeated from the opening retain their initial response.
    return (document, (before + token)[-160:], first, opening), value

programs.haiku:
"""Interjections and greetings that open an utterance."""
import re

READS = ()

OPENERS = {
    "hello": 5.0, "hi": 3.0, "hey": 3.0, "hola": 1.5, "ah": 3.0, "okay": 3.0, "wow": 3.0,
    "hmm": 3.0, "great": 2.0, "excellent": 2.0, "wait": 1.0, "good": 1.0, "thanks": 0.5,
    "yes": 0.5, "well": 0.5, "dear": 1.0, "haha": 2.0, "ugh": 2.0, "ok": 0.5, "yep": 1.0,
}
CONNECT = {"so", "but", "this", "that", "i", "let"}
RESET = set(".!?:\"“”|")
WINDOW = 4

def _word(s):
    return re.sub(r"[^a-z']", "", s.strip().lower())

def _punct(s):
    return any(c in s for c in ",!.?\n")

def step(carry, prefix, upstream):
    seg, doc = carry if carry is not None else ([], None)
    if prefix.document_ids[-1] != doc:
        seg = []
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    w = _word(s)
    value = 0.0
    k = len(seg)
    if seg and seg[0] in OPENERS and 1 <= k <= WINDOW:
        if _punct(s) or w in CONNECT:
            value = -OPENERS[seg[0]]
    if "\n" in s or "<|" in s or any(c in RESET for c in s) or not s.strip():
        seg = []
    elif w:
        seg = seg + [w]
    elif seg:
        seg = seg + [","]
    return (seg, doc), float(value)

programs.sol:
"""A negative lexical detector for supervision and monitoring.

The strongest responses are to English supervision words and the Chinese
character meaning supervise, with weaker responses to monitoring and oversight.
The weaker 'sup' spelling also fires outside that meaning. A short spelling
tail joins split words and UTF-8 characters; everything else predicts zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', b'')
    _, tail, raw_tail = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    text = (raw_tail + raw).decode('utf-8', errors='ignore')
    joined = tail + token
    match = re.search(r'[A-Za-z]+\Z', joined)
    word = match[0][-40:].lower() if match else ''
    part = token.lower().strip()
    bare = part.strip('._-')
    value = 0.0

    if re.search(r'superv(?:i(?:s[a-z]*)?)?\Z', word) or word == 'unsup':
        if 'superv' in part:
            value = -6.8 if part.endswith('ion') else -5.4
            if part.endswith(('or', 'ors')):
                value = -4.9
        elif word == 'unsup':
            value = -8.0
        elif part.startswith(('erv', 'is', 'vis')):
            value = -10.0
            if part == 'erv':
                value = -12.5
            elif part in ('ision', 'vision', 'ised', 'ising'):
                value = -8.5
            elif part == 'ises':
                value = -4.5
            if part.endswith(('or', 'ors')):
                value = -4.0
    elif word.endswith('immunosup') and part == 'up':
        value = -5.5
    elif word.endswith('suppressive') and part == 'pressive':
        value = -2.5
    elif bare == 'sup' or (part == 'up' and word.endswith('sup')):
        value = -0.8 if token[:1].isspace() else -1.0
        if token.istitle() and not token[:1].isspace():
            value = -0.4
    elif re.search(r'monitor(?:ing|ed|s)?\Z', word):
        value = -3.0 if word.endswith('ing') else -2.2
        if word.endswith('monitors'):
            value = -1.2
    elif re.search(r'surveillance\Z', word):
        value = -1.8
    elif word.endswith('regulatory'):
        value = -1.5
    elif word.endswith('regulators'):
        value = -0.75
    elif 'oversee' in word or word.endswith('oversight'):
        value = -0.85
    elif word.startswith('suiv'):
        value = -0.8

    current = raw.decode('utf-8', errors='ignore')
    completed = text[-1:] if not current and text else current
    if '监' in completed or '監' in completed:
        value = -5.5
        if completed in ('监听', '監聽'):
            value = -0.9
        elif completed in ('监狱', '監獄'):
            value = -0.4
        elif completed in ('监', '監', '监事', '監事'):
            value = -11.0
        elif '监督' in completed or '監督' in completed:
            value = -7.5 if len(completed) == 2 else -4.0
        elif '监控' in completed or '監控' in completed:
            value = -3.6
        elif ('监测' in completed or '監測' in completed
              or completed in ('总监', '總監')):
            value = -2.2
        elif completed in ('证监会', '證監會'):
            value = -4.3
    elif token == '督':
        value = -9.5 if text.endswith(('监督', '監督')) else -2.0
    elif (token in ('管', '视', '視', '局', '会', '會')
          and text[-2:-1] in ('监', '監')):
        value = -5.5
    elif text.endswith('감독'):
        value = -7.5

    return (document, joined[-40:], raw[-6:]), value

"""A sparse spelling detector, chiefly HAPPY, HENRY and short H syllables.

Happy's capitalization and token boundaries change its strength. Split words
such as hen+ry and h+app are stronger than their whole-token counterparts.
Other spelling responses include holy, hop, French heure, and a few positive
H syllables. This is not a general happiness or H-word classifier.
"""
import re

READS = ()

# Responses when a new token continues a final H (not CH, SH or TH).
H_ENDINGS = {
    'app': -13.0,
    'appy': -8.3,
    'ap': -3.2,
    'aps': -4.5,
    'op': -3.5,
    'opp': -7.0,
    'opper': -4.8,
    'oppers': -4.8,
    'opi': -2.2,
    'ari': -5.4,
    'arry': -5.0,
    'ry': -2.4,
    'oly': -4.8,
    'ao': 4.0,
    'au': 2.7,
    'ase': 2.2,
    'oo': 1.8,
    'oot': 2.1,
    'ai': -2.3,
    'ubble': -0.95,
}


def response(word, token):
    s = token.strip()
    low = s.lower()
    if low == 'happy':
        return -9.0 if s != low else (-4.9 if token.startswith(' ') else -8.4)
    if low == 'unhappy':
        return -6.0
    if low in ('happier', 'happiest'):
        return -4.5
    if low == 'happily':
        return -2.7
    if low == 'happiness':
        return -1.3
    if low == 'happ':
        return -3.3 if s != low else -6.5
    if low == 'hap':
        return -2.0
    if low in ('henry', 'henri'):
        return -3.35
    if low == 'harry':
        return -0.35
    if low == 'hari':
        return -5.0 if s != low else -2.1
    if low in ('holy', 'holly', 'unholy'):
        return -4.9 if low == 'unholy' else -2.3
    if low in ('hop', 'hops', 'hopping', '-hop'):
        return -1.5
    if low == 'hp':
        return -1.5 if token.startswith(' ') else -0.6
    if low == 'heure':
        return -1.5
    if low == 'hao':
        return 4.5
    if low in ('hue', 'hues'):
        return 2.0
    if low == 'hiệu':
        return 5.2
    if low == 'hu':
        return 0.46
    if low in ('app', '-app', '.app', '/app') and not token.isalpha():
        return 0.38

    if not token.isalpha():
        return 0.0
    w = word.lower()
    if w.endswith('hen') and low in ('ry', 'ri'):
        return -9.5
    if w.endswith('hal') and low == 'py':  # enthalpy
        return -10.1
    if w.endswith('math') and low == 'op':  # TeX's mathop
        return -4.0
    if w.endswith('happ'):
        if low in ('i', 'y', 'ily'):
            return -11.2
        if low in ('en', 'ens', 'ent', 'yn'):
            return -4.7
    if w.endswith(('he', 'heure')) and low in ('ur', 'use', 'ux', 'uses'):
        return -4.8
    if w.endswith('honne') and low == 'ur':
        return -2.5
    if w.endswith('hol') and low == 'iness':
        return -3.4
    if 'phen' in w[-7:] and low in ('y', 'yl'):
        return -1.4
    if w.endswith('h') and not w.endswith(('ch', 'sh', 'th')):
        return H_ENDINGS.get(low, 0.0)
    if w.endswith('ch') and low == 'ao':
        return 3.4
    if w.endswith('he') and low == 'app':
        return -8.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(word, token)
    match = re.search(r'[^\W\d_]+$', word + token)
    return (doc, match[0][-40:] if match else ''), value

"""A partial token-shape predictor for this very weak component.

Boundary tokens behave differently: the first uses length, case and function-word
classes; a second-position colon gets a positive offset. Later predictions are
near zero, with small numeric, script and punctuation adjustments. Content-word
identity and long-range context are deliberately not modeled.
"""
import math
import regex

READS = ()
DETERMINERS = frozenset(
    "the a an this that these those each every either neither some any no "
    "all both another such".split()
)
PRONOUNS = frozenset(
    "i me my mine myself you your yours yourself he him his himself "
    "she her hers herself it its itself we us our ours ourselves "
    "they them their theirs themselves".split()
)


def only(text, characters):
    return bool(text) and all(c in characters for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    raw = prefix.token_strings[-1]
    text = raw.strip()
    letters = text.isalpha()
    state = (doc, position)

    # Repeated centered dots (leaders/fillers) are an unusually negative case.
    if len(text) > 1 and only(text, "·"):
        return state, -0.87

    if position == 0:
        value = 0.017659
        value += 0.068894 * raw.startswith(" ")
        value += -0.094056 * ("\n" in raw)
        value += -0.162211 * ("\t" in raw)
        value += -0.387171 * ("\xa0" in raw)
        value += 0.188458 * (not text)
        if letters:
            value += -0.052399 * math.log1p(len(text))
            value += -0.074183 * (text.istitle() and not text.isupper())
            value += -0.062652 * (not text.isascii())
        elif any(c.isalpha() for c in text):
            value += -0.114399
        value += 0.156382 * (text.lower() in DETERMINERS)
        value += 0.149826 * (text.lower() in PRONOUNS)
        value += 0.117653 * (bool(text) and text.isdecimal())
        value += 0.160131 * (text == "1")
        for characters, offset in (
            ("#", -0.236511), (".", 0.252212), (",", 0.126449),
            ("()", -0.086184), (";", 0.260918), ("-", 0.174325),
        ):
            if only(text, characters):
                value += offset
        return state, float(value)

    if position == 1:
        return state, 0.002398 + 0.280729 * only(text, ":")

    value = -0.002525 + 0.005423 * letters
    value += -0.003422 * raw.startswith(" ")
    value += -0.003962 * (bool(text) and text.isdecimal())
    for script, offset in (
        ("Hiragana", -0.025635), ("Greek", -0.026632), ("Hangul", -0.021674),
    ):
        if regex.search(r"\p{Script=" + script + "}", text):
            value += offset
    for characters, offset in (
        ("`", -0.033197), ("，", -0.022997), ("_", -0.023244),
        ("[]", 0.016689), ("—", -0.027954), ("|", -0.018321),
    ):
        if only(text, characters):
            value += offset
    if len(text) > 1 and only(text, "*"):
        value += -0.054261
    return state, float(value)

"""A sparse approximation to a document-opening pulse.

Question labels and source-code/TeX syntax at the start of a document give
positive pulses. Month names (especially abbreviations) are also positive;
digits have a small negative offset. These rules also apply
to an unbroken initial repetition of the same token (e.g. tab indentation).
Other positions get only the small background mean; lexical variation in
ordinary prose is deliberately not modeled.
"""
import re
import calendar

READS = ()
MONTH_NAMES = frozenset(calendar.month_name[1:])
MONTH_ABBREVIATIONS = frozenset(calendar.month_abbr[1:]) - MONTH_NAMES

# Recognizable source-file openings, not a vocabulary-wide token table.
SOURCE_OPENINGS = {
    'import': 1.94,
    'from': 0.93,
    'package': 0.79,
    'using': 0.19,
    '#include': 1.64,
    '#pragma': 0.74,
    '{': 1.13,
    '{\n': 1.38,
    '/*\n': 0.88,
    '/**\n': 0.36,
    '"""': 0.55,
    '"""\n': 1.24,
}


def opening_value(text):
    if text in SOURCE_OPENINGS:
        return SOURCE_OPENINGS[text]
    if text == '<|endoftext|>':
        return 1.87
    if text == '<|im_start|>':
        return 0.10
    if text in ('Q', 'Question'):
        return 1.43 if text == 'Q' else 1.80
    if text in ('¿', '¡'):
        return 1.76 if text == '¿' else 1.20
    if text == '\t':
        return 1.95
    if re.fullmatch(r'[ {(_]*\\', text):
        return 1.82 if text == '\\' else 1.40
    if text in ('*', '**'):
        return 1.27 if text == '*' else 2.07
    if text in MONTH_ABBREVIATIONS:
        return 1.1
    if text in MONTH_NAMES:
        return 0.36
    if text.isdigit():
        return -0.22
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        opening = text
    else:
        opening = carry[1]
        if text != opening:
            opening = None
    value = opening_value(text) if opening is not None else 0.0014
    return (doc, opening), value

programs.haiku:
"""First token of a document (its position 0, where attention sees only that token).

The component's activation there depends only on which token it is. Two concepts carry most of it:
code or markup openers (import, #include, package, a tab, a backslash, a brace, a comment opener)
and question openers (Q, Question), which are strongly positive; digits are mildly negative.
Everywhere else the program predicts 0 (the component's typical value is near 0 mid-document)."""
READS = ()

CODE_OPENERS = {"import", "#include", "package", "from", "const", "try", "test", "\\", " \\", "_\\",
                "\t", "{", "{\n", "*", "/*\n", '"""\n'}
QA_OPENERS = {"Q", "Question"}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if tok in CODE_OPENERS or tok in QA_OPENERS:
            return carry, 1.4
        if tok in DIGITS:
            return carry, -0.2
    return carry, 0.0

programs.sol:
"""A partial English spelling/inflection approximation.

Positive cues: clipped -ing, archaic verb endings and words, poetic
apostrophe-d, and optional plural markers. Unusual -s inflections and
uppercase-S endings are weakly negative. Dictionaries, word frequencies,
and local language/register cues limit accidental fragment matches.
Document-initial Title: is modeled separately. Most positions are zero.
These rules cover only a small part of the component's variation.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency
import wordnet
import inflect

READS = ()
ENGLISH = {'the', 'of', 'and', 'to', 'for', 'with', 'is',
           'that', 'you', 'it', 'he', 'she', 'my', 'your', 'we',
           'i', 'but', 'not', 'was', 'had', 'been', 'are', 'from', 'our',
           'without', 'when', 'they', 'them', 'this', 'have'}
BIOLOGY = re.compile(
    r'\b(?:proteins?|expression|cells?|apoptosis|receptors?|plasmids?|'
    r'antibodies|antibody|promoter|inhibition|kinase|tissues?|'
    r'knockdown|cytoskeleton|tumou?rs?|samples?|proliferation)\b', re.I)
ENDINGS = {'in', 'lin', 'tin', 'nin', 'eth', 'th', 'h', 'est', 'st',
           "'d", '’d', 's', 'S', '(s', '[s'}
INFLECTION = inflect.engine()


@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word.lower(), 'en') if word else 0.0


@lru_cache(maxsize=8192)
def parts(word):
    return wordnet.parts_of_speech(word.lower()) if word else set()


@lru_cache(maxsize=8192)
def is_verb(stem):
    if len(stem) < 2:
        return False
    roots = [stem, stem + 'e']
    if len(stem) > 2 and stem[-1] == stem[-2]:
        roots.append(stem[:-1])
    return any('verb' in parts(r) and frequency(r) > 2.5 for r in roots)


@lru_cache(maxsize=8192)
def irregular_plural(stem):
    return INFLECTION.plural_noun(stem.lower()) != stem.lower() + 's'


def ending_value(token, base, context, previous=''):
    capitals = base.isupper()
    word = (base + token).lower()
    base = base.lower()
    words = set(re.findall(r'[a-z]+', context.lower()))
    english = bool(words & ENGLISH)
    biological = bool(BIOLOGY.search(context))
    if token in ('in', 'lin', 'tin', 'nin') and len(word[:-2]) >= 2:
        full = frequency(word + 'g')
        if full > 2.5 and full > frequency(word) + 0.2 and english:
            if parts(word) or biological:
                return 0.8
            return max(0.0, 3.0 + 1.1 * (full - 4.0))
    elif token in ('eth', 'th', 'h') and base and english and '\\' not in context:
        if word in ('doth', 'saith', 'hath'):
            return 4.8
        if word.endswith('eth') and is_verb(word[:-3]):
            return 1.0 if biological else 5.5
    elif token in ('est', 'st') and base:
        if words & {'thou', 'thy', 'thee'}:
            if word.endswith('est') and is_verb(word[:-3]):
                return 3.5
            if word in ('didst', 'dost', 'hast'):
                return 2.0
    elif token in ("'d", '’d') and is_verb(base):
        return 1.0 if token == "'d" else 0.3
    elif token == 's' and len(base) > 1:
        if 'noun' in parts(base) and irregular_plural(base):
            return -1.2
        stem = re.search(r'[A-Za-z]+\Z', previous)
        stem = stem[0].lower() if stem else base
        gap = frequency(stem) - frequency(stem + 's')
        return -0.2 * max(0.0, gap - 0.5)
    elif token == 'S' and capitals and len(base) > 1:
        return -0.25 * max(0.0, frequency(base) - 3.0)
    elif token in ('(s', '[s') and base:
        return 0.18 if token == '(s' else 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0)
    _, tail, count = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in ENDINGS:
        match = re.search(r'[A-Za-z]+\Z', tail)
        base = match[0] if match else ''
        previous = prefix.token_strings[-2] if count else ''
        value = ending_value(token, base, tail, previous)
    elif token == ' unto':
        value = 1.6
    elif token in (' thee', ' hath'):
        value = 0.7
    if count == 0 and token == 'Title':
        value = -0.59
    elif count == 1 and tail == 'Title' and token == ':':
        value = 4.85
    return (doc, (tail + token)[-120:], count + 1), value

programs.haiku:
"""Archaic and dialect verb endings and a few stable suffix fragments.

Predicts the component's activation on the current token. Its large positive
values come from archaic 3rd-person verb endings (-eth: provoketh, goeth;
doth, hath, unto, thee) and informal dropped-g '-in' verbs (sayin', tellin'),
and from the 'Title:' marker after <|endoftext|>; plural and capital-S
fragments are mildly negative. All values are shrunk by half, because the
large events are rare and the unshrunk values did not generalize.
"""
READS = ()
SHRINK = 0.5
ARCHAIC = {"doth", "hath", "saith", "unto", "thee", "thou", "thy", "thine"}
DROPPED_G_STEMS = set("klvpytd")


def word_so_far(prefix):
    """The current word up to this token (letters since the last space)."""
    text = ""
    for s in reversed(prefix.token_strings):
        text = s + text
        if s[:1].isspace() or s == "":
            break
    return text.strip()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = word_so_far(prefix)
    low = word.lower()
    inside = not tok[:1].isspace()
    value = 0.0
    if prev == "Title" and tok == ":":
        value = 1.7
    elif inside and low.endswith("eth") and len(low) >= 5:
        value = 1.8 if word[:1].islower() else 0.5
    elif low in ARCHAIC:
        value = 0.7
    elif inside and low.endswith("in") and len(low) >= 5 and low[-3] in DROPPED_G_STEMS:
        value = 0.6
    elif inside and tok == "S":
        value = -0.14
    elif inside and tok == "s":
        value = -0.08
    elif tok == "··":
        value = -0.35
    return carry, SHRINK * value

programs.sol:
"""Approximate the numeral-related part of this component.

Multiplication-by-ten notation and English magnitude words are negative;
low-order number words and non-ASCII numeral continuations are positive.
Retain only 160 bytes of context, reset at document boundaries, and predict
zero on unrelated text and the first three tokens of each document.
Irregular lexical and document-start responses are not modeled.
"""
import re
import unicodedata as ud
import inflect

READS = ()
_engine = inflect.engine()
UNITS = {_engine.number_to_words(n) for n in range(10)}
TEENS = {_engine.number_to_words(n) for n in range(10, 20)}
TENS = {_engine.number_to_words(n) for n in range(20, 100, 10)}
SCALES = {'hundred', 'thousand'}
NUMBERS = UNITS | TEENS | TENS | SCALES | {'million', 'billion', 'trillion'}
MULTIPLY = r'(?:[xX×*]|\\times|\\cdot)[^\S\n]*'


def digit_tail(text):
    """Length of a run of non-ASCII small numerals, excluding magnitude signs."""
    n = 0
    for ch in reversed(text):
        value = ud.numeric(ch, None)
        if ch.isascii() or value is None or value >= 10:
            break
        n += 1
    return n


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw, pos = carry[1:] if carry and carry[0] == doc else (b'', 0)
    token = prefix.token_strings[-1]
    new = (raw + prefix.token_bytes[-1])[-160:]
    state = (doc, new, pos + 1)
    if pos < 3:
        return state, 0.0
    before = raw.decode('utf-8', 'replace')
    word = token.strip().lower().lstrip('-')
    value = 0.0
    if token in ('0', '1'):
        match = re.search(MULTIPLY + ('1$' if token == '0' else '$'), before)
        if match:
            factor = before[:match.start()].rstrip()
            if re.search(r'\d[.,]\d+$', factor):
                value = -0.91 if token == '0' else -0.34
            elif re.search(r'\d$', factor):
                value = -0.44 if token == '0' else -0.075
    elif word in NUMBERS:
        text = re.sub(r'([a-z])([A-Z])', r'\1 \2', before).lower()
        words = re.findall('[a-z]+', text)[-6:]
        last = words[-1] if words else ''
        previous = words[-2] if len(words) > 1 else ''
        after_digit = bool(re.search(r'[0-9][^\S\n]*$', before))
        if word in SCALES:
            value = -0.94 if after_digit else -0.33 if last in NUMBERS else -0.09
        elif word in UNITS | TEENS | TENS:
            value = -0.14 if word in TENS else -0.047 if word in TEENS else 0.0
            if after_digit:
                value = -0.07 if word == 'one' else -0.3
            elif last in ('negative', 'minus', 'plus', 'times'):
                value = 0.3
            elif last in NUMBERS and re.search('[a-z][ -]*$', text):
                value = 0.9 if 'point' in words[-4:] else 0.4
                if last in SCALES:
                    value = 0.7
            elif last in ('and', 'to', 'of', 'point'):
                if previous in NUMBERS:
                    value = 0.85 if previous in SCALES else 0.55
                    if last == 'point':
                        value = 0.8
                    elif word in TENS and previous not in SCALES:
                        value = -0.1
                elif any(w in NUMBERS for w in words[-4:-1]):
                    value = 0.3
    else:
        # Decode joined bytes to recognize a numeral completed by a split token.
        text = new.decode('utf-8', 'ignore')
        prior = raw.decode('utf-8', 'ignore')
        s = token.strip() if '\ufffd' not in token else text[-1:]
        if s:
            name = ud.name(s[0], '')
            n = digit_tail(prior)
            numeric = ud.numeric(s[0], None)
            if 'ARABIC' in name and 'DIGIT' in name:
                value = 0.65 if n else 0.35
            elif 'FULLWIDTH' in name and 'DIGIT' in name:
                value = 0.03 if n else 0.0
            elif 'SUBSCRIPT' in name and numeric is not None:
                value = 0.07
            elif 'SUPERSCRIPT' in name:
                value = 0.12 if '\ufffd' in token and numeric is not None else 0.0
            elif numeric is not None and not s[0].isascii() and numeric < 10:
                value = 0.8 if n >= 2 else 0.09 if n else 0.0
            elif token == '年' and n >= 3:
                value = 0.7
    return state, value

programs.haiku:
"""Layer-1 MLP down-projection component 3788, as a readable rule set.

What it does: this component is weak and mostly diffuse. Its activation is near zero on
almost every token, with idiosyncratic per-token values that no simple concept predicts. The
concepts it does respond to are:

1. Number phrases. On the "0" of a scientific-notation power of ten ("8.6×10", "×10^8") it is
   negative. On "hundred"/"thousand" after a number word it is mildly negative. On a number
   word that completes a compound number ("hundred and [twenty]", "three hundred [six]") it is
   positive.
2. The first token of a document. Nothing precedes it, so its value depends only on the token
   itself. A digit there is positive and a special token such as "<|im_start|>" is negative.

Everywhere else the program predicts 0. The values are rounded group means, not fitted.
"""
READS = ()

MULT = {"×", "x", "*", "\\times"}
SCALE = {"hundred", "thousand", "million", "billion"}
NUMBER_WORDS = {
    "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
    "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen",
    "eighteen", "nineteen", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
    "eighty", "ninety",
}


def recent(prefix, k):
    """The token k steps back from the current one, lower-cased and stripped; '' if it lies
    before the start of the current document."""
    i = len(prefix.token_strings) - 1 - k
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    cur, p1, p2 = recent(prefix, 0), recent(prefix, 1), recent(prefix, 2)
    if len(prefix.token_strings) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        # first token of a document: its value depends only on the token itself
        if cur.isdigit():
            return None, 0.3
        if prefix.token_strings[-1].startswith("<|"):
            return None, -0.3
        return None, 0.0
    if cur == "0" and p1 == "1" and p2 in MULT:
        return None, -0.6          # the zero of "×10^n"
    if cur in SCALE and p1 in NUMBER_WORDS:
        return None, -0.25         # "eighteen hundred"
    if cur in NUMBER_WORDS and p1 in SCALE:
        return None, 0.8           # "three hundred [six]"
    if cur in NUMBER_WORDS and p1 == "and" and (p2 in SCALE or p2 in NUMBER_WORDS):
        return None, 0.7           # "hundred and [twenty]"
    return None, 0.0

programs.sol:
"""Starts of tests are positive; starts of quoted blocks are negative.

Recognize test identifiers, declarations, annotations, and description calls.
The strength depends on visible syntax: a test declaration is stronger than
`test` in prose. URL scheme separators are also positive. Opening quotations
and heredocs are negative, as are Go method-receiver openings. Everything
else is zero, except a small negative default on a document's first token.
Only the last 256 characters of the current document are kept.
"""
import re

READS = ()
TEST_NAMES = {'pytest', 'vitest', 'conftest', 'supertest', 'unittest', 'httptest'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, before)
    if not before and value == 0.0:
        value = -0.15
    return (doc, (before + token)[-256:]), value


def activation(token, before):
    s, end = token.strip(), before.rstrip()
    line_start = not end or bool(re.search(r'\n\s*$', before))

    if s == '://' or (s == '//' and end.endswith(':')):
        return 1.33

    # The word test, with ordinary path/identifier delimiters and inflections.
    m = re.fullmatch(
        r'([/._(:-]*)(test|Test|TEST|tests|Tests|testing|Testing)', s)
    if m:
        punctuation, word = m.groups()
        if word.lower() == 'testing':
            value = 0.28 if word[0].isupper() else 0.15
        elif word.lower() == 'tests':
            value = 0.25 if token[:1].isspace() else 1.2
            if punctuation:
                value = 0.4
            if word[0].isupper():
                value = 0.72
        else:
            value = 0.75 if word[0].isupper() else 0.42
            if not token[:1].isspace():
                value = 0.75 if word[0].isupper() else 0.85
            if punctuation:
                value = {'.': 1.05, '/': 0.65, '_': 0.28}.get(punctuation, 0.4)
                if punctuation == '/' and word[0].isupper():
                    value = 1.6
            if end.endswith('::'):
                value = 1.67
            elif end.endswith('/'):
                value = 0.94
            elif line_start and not punctuation:
                value = 1.2 if word == 'test' else 0.8
            if not punctuation:
                if re.search(r'\bdef\s*$', before):
                    value = 3.3
                elif end.endswith('func') and word == 'Test':
                    value = 3.8
                elif re.search(r'\bfunction\s*$', before):
                    value = 3.5 if 'public function' in before[-40:] else 1.6
                elif re.search(r'\bvoid\s*$', before):
                    value = 2.6
                elif re.search(r'\bfn\s*$', before):
                    value = 2.0
                elif re.search(r'\b(?:from|import)\s*$', before):
                    value = 1.4
                elif re.search(r'#\[\s*$', before):
                    value = 1.2 if end.endswith(('"#[', "'#[")) else 4.0
                elif end.endswith('@') and word == 'Test':
                    value = 3.0
                elif re.search(r'\bclass\s*$', before):
                    value = 2.2
                elif word == 'TEST' and line_start:
                    value = 2.4
            if punctuation == '/' and re.search(
                    r'\bPASSED\b|\.py::|(?:^|/)tests(?:/[^\s]*)?$',
                    before[-200:]):
                value = 1.75
            elif punctuation in ('', '/') and re.search(
                    r'\b(?:RUNS?|FAIL|PASS)\b', before[-80:]):
                value = max(value, 1.15)
        return value

    # Test annotations and the declarations they introduce.
    if s == '@Test':
        return 1.8
    if s == 'TestMethod' and end.endswith('['):
        return 3.2
    if s == 'void':
        if re.search(r'(?:@Test|\[Test\w*\])[^{};]{0,70}$', before):
            return 3.2
        if re.search(r'@(?:Before|After)\w*[^{};]{0,60}$', before):
            return 1.7
    if s == 'fn' and re.search(r'#\[test\][^{};]{0,40}$', before):
        return 2.0
    if s == ',' and re.search(r'\bTEST(?:_[FP])?\([^,\n]*$', before):
        return 3.3
    if s in ('_F', '_P') and end.endswith('TEST'):
        return 2.2
    if s == '.Run' and re.search(r'\bt$', before):
        return 1.9
    if s == '.T' and end.endswith('testing'):
        return 0.65
    if s == 'est':
        fragment = re.search(r'[A-Za-z_]*$', before).group()
        if fragment + s in TEST_NAMES:
            return 1.7

    if s in ('it', 'describe', 'suite', 'context') and line_start:
        if re.search(r'\b(?:describe|suite|expect)\b', before):
            return 0.55 if s == 'it' else 0.85

    # Opening the first string argument of a test-description call.
    if s in ('"', "'", '("', "('") and re.search(
            r'\b(?:it|test|describe|suite|context|t\.Run)\s*$', before):
        if '(' in s:
            return 2.5
        if re.search(r'(?:^|\n)[\t \d]*\w+\s*$', before):
            return 1.1

    # Contrasting non-test block openings.
    if token == ' (' and end.endswith('func'):
        return -1.35
    if s.isidentifier() and s.isupper() and re.search(r'<<-?\s*[\'"]?$', before):
        return -1.8
    if s == r'\"':
        return -0.14
    q = re.fullmatch(r'[\s(:]*(["“«‘„])([A-Z][a-z]*)?', token)
    if q:
        quote, first_word = q.groups()
        code_quote = end.endswith(('":', "':", '{', '[', ',', '='))
        if first_word:
            return -1.0 if quote != '"' else -0.8
        if line_start and not code_quote:
            return -0.4 if token[:1].isspace() else -1.0
        if not code_quote and end.endswith(('.', ':', '!', '?', ')')):
            return -0.45 if quote != '"' else -0.25
    if s in ('：“', '。“', '，“', '、“'):
        return -0.15
    return 0.0

"""Approximate a spelling-sensitive response to short er/r syllable pieces.

It is strongest when a split token completes under-, inter-, counter- and
related prefixes. Other er onsets have smaller, signed responses. Complete
common words are mostly ignored; long/short term and German prefix fragments
have their own rules. State retains the last 24 trailing letters, resetting
at document boundaries; unmatched tokens receive zero or a small er baseline.
"""
import re
import unicodedata

READS = ()


def response(token, word):
    s = token.lower().translate(str.maketrans('éèêë', 'eeee'))
    bare = s.strip()
    if bare in ('term', '-term'):
        if word.lower() in ('long', 'short'):
            return 2.93 if word.lower() == 'long' else 1.70
        if bare == '-term':
            return 0.78
    if bare in ('unter', 'unters'):
        return 4.35 if len(bare) > 5 else 1.50
    if bare in ('counter', 'counters'):
        return 4.35 if len(bare) > 7 else 0.62
    if s[:1].isspace() and re.fullmatch(r'ver[egmz]', bare):
        return 1.37
    if bare == 'over':
        return 0.17
    if bare == 'ker' and s[:1].isspace():
        return -1.25

    # Smaller negative response for rho immediately after epsilon.
    if bare == 'ρ':
        before = unicodedata.normalize('NFD', word)[-2:]
        if 'ε' in before:
            return -0.84 if len(word) == 1 else -0.59

    i = s.find('er')
    if i < 0 or i > 2 or len(s) - i > 3 or s[:1].isspace():
        return 0.0
    before = re.search(r'[a-zäöüßſ]*$', word.lower() + s[:i])[0]
    before = before.replace('ſ', 's')
    factor = 0.65 if s.endswith('er') else 1.0
    # Short tokens that complete relational prefixes.
    if before in ('count', 'unt', 'und'):
        return 8.01 * factor
    if before == 'int':
        return 5.26 * factor
    if before.endswith(('unt', 'ünt', 'int', 'ant')):
        return 2.33 * factor
    if before in ('un', 'uns') or before.endswith('and'):
        return 2.60 * factor
    if before.endswith(('üb', 'ueb')) or before == 'ob':
        return 4.52 * factor
    if before.endswith(('sup', 'imp', 'emp')):
        return 1.62 * factor
    # Several other er onsets contribute with a negative sign.
    if before.endswith('exc') and i == 1:
        return -5.75
    if before.endswith('ex'):
        return -0.86
    if before.endswith(('schm', 'rem')) or before == 'em':
        return -1.76
    if before.endswith('sch'):
        return -1.18
    if before.endswith(('auss', 'äuss')):
        return 2.31 * factor
    if before in ('unv', 'unc'):
        return 4.40 * factor
    if i > 0:
        return 0.0
    if before.endswith('v'):
        return 1.32 * factor
    if before.endswith(('c', 'k')):
        return -0.63
    if before.endswith('cl'):
        return -1.41
    if before.endswith(('t', 'd')):
        return 0.37 * factor
    if before.endswith('b'):
        return 0.55 * factor
    if before.endswith('m'):
        return 0.08 * factor
    if before.endswith('p'):
        return 0.47 * factor
    return -0.04 * factor


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, word)
    word = re.search(r'[^\W\d_]*$', word + token)[0][-24:]
    return (doc, word), float(value)

"""Predict a strong negative response to a function's opening return statement.

Headers are recognized by punctuation and keywords, with extra strength for
accessors. Later returns weaken with distance and intervening control flow.
The history contains only the last 128 tokens and resets between documents.
Smaller rules cover powers, LaTeX groups, code braces, quoted lists, empty-body
`pass`, and repeated middle-dot separators. All other tokens predict zero.
These are syntax heuristics, not a full parser or an exact activation model.
"""
import re

READS = ()
CONTROL = re.compile(
    r'\b(if|else|for|while|switch|catch|try|with|except|elif|class|struct|impl)\b'
)
ACCESSOR = re.compile(r'\b(?:get|Get|is|Is)[A-Z_]|\bget\s*\{')


def clean_line(line):
    # Code listings sometimes put a line number before a tab.
    return re.sub(r'^\s*\d+\t', '', line).strip()


def function_header(line):
    return bool(
        not CONTROL.search(line) and not re.match(r'return\b', line)
        and (')' in line or re.search(r'\b(def|function|func|fn|get)\b', line))
    )


def complete_header(lines, j):
    """Include a preceding line for a brace, and multiline parameter lists."""
    header = lines[j]
    if header == '{' and j > 0:
        j -= 1
        header = lines[j] + ' {'
    balance = header.count('(') - header.count(')')
    while balance < 0 and j > 0:
        j -= 1
        header = lines[j] + ' ' + header
        balance += lines[j].count('(') - lines[j].count(')')
    return header


def return_value(history, text):
    lines = [clean_line(line) for line in text.split('\n')]
    j = len(lines) - 1
    while j >= 0 and not lines[j]:
        j -= 1
    header = complete_header(lines, j) if j >= 0 else ''
    first = j >= 0 and lines[j].endswith(('{', ':'))
    if first and function_header(header):
        if ACCESSOR.search(header):
            return -14.3
        gap = next((k + 1 for k, s in enumerate(reversed(history))
                    if '\n' in s or '\\n' in s), 128)
        return -12.0 if gap <= 4 or text.rstrip().endswith('{') else -8.5
    if lines[-1]:
        if re.search(r'[@#*/]\s*$', text):
            return -0.3
        return 0.7 if re.search(r'\belse\s*$|\)\s*$', text) else 0.2
    for k in range(j, -1, -1):
        opens_block = lines[k].endswith(('{', ':'))
        if opens_block and function_header(complete_header(lines, k)):
            if any(CONTROL.search(line) for line in lines[k + 1:]):
                return -0.3
            age = j - k
            if age == 1:
                return -5.5
            return -4.0 if age <= 4 else -1.3
    return -0.2 if any(CONTROL.search(line) for line in lines[-5:]) else -0.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    if word == 'return' or '{' in token or '^' in token or word == 'pass':
        before = ''.join(history)
        text = before.replace('\\n', '\n').replace('\\t', '\t')
        tail = text.rstrip()
        if word == 'return':
            value = return_value(history, text)
        elif word == 'pass':
            if re.search(r'\b(def|class)\b[^\n]*:\s*$', text):
                value = -5.5
        elif word.startswith('^'):
            if re.search(r'\be$', tail):
                value = -2.2
            elif re.search(r'\{(?:\\+(?:text|mathrm)\{)?e\}\}?$', tail):
                value = -1.0
            elif tail.endswith('}'):
                value = 2.6 if re.search(r'_\{[^{}]*\}$', tail) else 1.8
            else:
                value = -1.3 if word.startswith('^(') else 0.2
        elif word.startswith('{'):
            if re.search(r'\be\^$', tail):
                value = -3.8
            elif re.search(r'\\sqrt\s*$', tail):
                value = -1.4 if '\\' in word else -0.9
            elif re.search(r'\\frac\s*$', tail):
                value = -1.0 if '\\' in word or word.startswith('{{') else -0.2
            elif re.search(r'\\begin\s*$', tail):
                value = 1.3
            elif word.startswith('{-'):
                value = -0.4
            elif tail.endswith('=>'):
                value = 1.3
            elif re.search(r'\bget\s*$', tail):
                value = -3.5
            elif re.search(r'\[\](?:[\w.:<>]+)\s*$', tail):
                value = -2.0
            elif not CONTROL.search(tail.rsplit('\n', 1)[-1]):
                if re.search(r'\)\s*->[^\n]+$', tail):
                    value = -1.5
                elif function_header(tail.rsplit('\n', 1)[-1]):
                    value = -0.2
    if word == '["' and ''.join(history[-2:]).endswith('List'):
        value = -2.5
    if word == '··':
        value = 1.0
    return (doc, (history + (token,))[-128:]), float(value)

"""Graphical-output words, distinguished from incidental word fragments.

Plotting APIs and axis labels receive the largest values. Figure references,
results and lowercase scientific-Python aliases receive weaker ones. A short text tail
adjusts plotting punctuation and code-control words, rejects narrative plots,
and separates LaTeX figure labels from attribute values and file paths.
This leaves many context-dependent code and smaller lexical responses out.
