import re

READS = ()
NARRATIVE = re.compile(r'\b(?:movie|film|novel|story|fiction|screenplay)\b', re.I)
PLOT_PREFIXES = {
    'gg', 'q', 'sub', 'bar', 'box', 'kde', 'coef', 'violin', 'scatter', 'line',
    'hist', 'density', 'pair', 'dist', 'joint', 'reg', 'count', 'strip', 'swarm',
}

PLOT_CONTEXT = re.compile(
    r'\b(?:plt|pyplot|matplotlib|fig|plot|scatter|imshow|subplot|'
    r'xlabel|ylabel|legend|ggplot)\b', re.I
)
PYTHON_CONTEXT = re.compile(
    r'\b(?:def|elif|except|import|None|True|False)\b|'
    r'\b(?:self|np|pd|plt)\.|```python|:\s*\n'
)
AXIS_SETTINGS = {'xlabel', 'ylabel', 'zlabel', 'xlim', 'ylim', 'zlim'}
PLOT_ACTIONS = {'plot', 'subplot', 'subplots', 'boxplot', 'barplot'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '')
    history = carry[1]
    syntax = history.replace('\\n', '\n').replace('\\t', '\t')
    raw = prefix.token_strings[-1]
    token = raw.strip()
    name = token.lstrip('._(/=')
    word = name.lower()
