    member = token.startswith(('.', '_'))
    line = syntax.rsplit('\n', 1)[-1]
    body = re.sub(r'^\s*(?:\d+[\t:]\s*)?[+-]?\s*', '', line)
    line_start = not body
    plotting = bool(PLOT_CONTEXT.search(history))
    python = bool(PYTHON_CONTEXT.search(syntax))
    code_name = member or line_start
    value = 0.0

    # Do not mistake a word fragment (French 'complot', for example) for a plot.
    continuation = (raw and raw[0].isalpha() and history
                    and history[-1].isalpha()
                    and not (raw[0].isupper() and history[-1].islower()))
    preceding_word = re.search(r'[A-Za-z]+$', history)
    plot_compound = (word == 'plot' and preceding_word
                     and preceding_word.group().lower() in PLOT_PREFIXES)
    library_compound = word == 'plotlib' and history.lower().endswith('mat')
    latex_figure = word == 'fig' and re.search(
        r'\\(?:label|ref)\{[^}]*$', history
