    split_plot = word == 'lot' and history.endswith('P')
    if continuation and not (plot_compound or library_compound
                             or latex_figure or split_plot):
        return (doc, (history + raw)[-180:]), 0.0

    if name == 'plt':
        value = 4.4 if line_start else 3.0
    elif word in {'pyplot', 'plotlib', 'matplotlib', 'seaborn'} or name == 'sns':
        value = 2.2 if word in {'pyplot', 'plotlib'} else 1.2
    elif word in PLOT_ACTIONS or (word == 'lot' and history.endswith('P')):
        value = (2.6 if attached else 1.0) + (0.7 if line_start else 0.0)
        if NARRATIVE.search(history[-100:]) and not member:
            value = 0.0
    elif word in {'plots', 'plotting', 'plotted'}:
        value = 0.7
    elif word in AXIS_SETTINGS:
        value = 3.4
    elif word in {'title', 'legend'}:
        value = 2.7 if plotting and code_name else 0.15
    elif word == 'fig' or word.removesuffix('s') == 'figure':
        value = 1.3 if attached and name.islower() else 0.15
        if latex_figure:
            value = 2.1
        elif re.search(r'''[\w-]+=["']$''', history):
            value = 0.4
        elif history.endswith('/') or 'node_modules/' in history:
            value = 0.15
    elif word in {'hist', 'histogram', 'histograms', 'imshow', 'scatter'}:
        value = 1.8 if member or line_start else 0.35
    elif word == 'show':
        value = 2.0 if member and plotting else 0.0
    elif word in {'draw', 'drawing', 'visualize'}:
        value = 1.4 if member and name.islower() else 0.15
    elif word.removesuffix('s') == 'result':
        value = 0.22
        if re.search(r'\b(?:search|showing|displaying)\s*$', history, re.I):
            value = 0.0
    elif name == 'np':
        value = 0.6
    elif name in {'pd', 'pandas'} or word == 'dataframe':
        value = 0.16
    elif name in {'else', 'elif', 'try'} and not member:
        value = -0.6 if line_start else -0.1
    elif name == 'except' and not member:
        value = -0.2 if line_start else -0.08
    elif word in {'sleep', 'exit'}:
        value = -0.7 if line_start or (member and (word == 'sleep' or
                re.search(r'\b(?:sys|os)$', history))) else 0.0
    elif token in {',', '],', '),'}:
        after_name = bool(re.search(r'[A-Za-z_]\w*$', syntax))
        value = 0.1 if python and after_name else 0.0
    elif token in {'=', '=(', "='", '="', '=['}:
        value = 0.3 if plotting else 0.0
    elif token in {'("', "('", '("\\', "('\\"}:
        value = 0.8 if plotting else 0.05

    return (doc, (history + raw)[-180:]), value

"""Whitespace-layout novelty, plus literal escape/LaTeX formatting.

Line-leading runs are negative when that spacing has little recent precedent.
Repeated spacing attenuates the response; opening delimiters soften it too.
Widths are grouped by customary four-column indentation (the last space often
belongs to the next word's token). Counts fade over about 100 tokens and
reset at document boundaries. LaTeX row breaks, nested string escapes and
two thinking-markup boundaries have separate estimates; ordinary text is zero.
"""
import math
import re

READS = ()
# Steady response and unfamiliar-spacing penalty, by indentation width.
SPACE_WIDTHS = (
    (-0.11, -0.83),  # one space
    (0.03, -1.48),   # two spaces
    (0.05, -0.86),   # one less than a multiple of four
    (-0.08, -1.38),  # multiple of four
    (-0.17, -0.96),  # other odd widths
    (-0.24, -0.91),  # other even widths
)
LATEX = re.compile(
    r'\\(?:begin|end|frac|sqrt|left|right|math\w+|text|hfill|hline|'
    r'alpha|beta|gamma|theta|phi|psi|Delta|le|ge|in|cdot|sum|cos|sin|ar)\b'
)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, {}, 0.0, '', '')
    _, position, history, all_spacing, previous, tail = carry
    value = 0.0
    pure = bool(s) and s.isspace() and '\n' not in s and '\r' not in s
    if pure:
        last, count = history.get(s, (-10000, 0.0))
        recent = count * math.exp(-(position - last) / 100)
        novelty = (1 - math.exp(-position)) / (
            1 + 2 * recent + 0.05 * all_spacing)
        n = len(s)
        spaces, tabs = not s.strip(' '), not s.strip('\t')
        if spaces or tabs:
            if previous.endswith('\n'):
                if spaces:
                    group = (n - 1 if n <= 2 else
                             {3: 2, 0: 3, 1: 4, 2: 5}[n % 4])
                    b, a = SPACE_WIDTHS[group]
                else:
                    depth = min(n - 1, 2)
                    b, a = -0.05 - 0.08 * depth, -0.46 + 0.05 * depth
                value = b + a * novelty
                end = previous.rstrip()[-1:]
                if end and end in '{[(':
                    value += (0.06 + 0.63 * novelty if spaces
                              else 0.16 + 0.25 * novelty)
                elif end:
                    if spaces:
                        value += 0.05
                    elif end in '}]);,':
                        value += 0.17 - 0.20 * novelty
                    elif end == ':':
                        value += 0.06 - 0.20 * novelty
                    else:
                        value -= 0.4 * novelty
                if previous.endswith(' \n'):
                    value += (-0.06 - 0.10 * novelty if spaces
                              else 0.05 - 0.06 * novelty)
            elif previous.endswith('\\n') or previous == 'n':
                value = -0.25 * novelty if spaces else 0.0
            elif previous.isspace():
                value = 0.023 if spaces else -0.07
            else:
                value = 0.0 if spaces else 0.10 - 0.026 * math.log1p(n)
            if position == 0:
                value += 0.24 if spaces else -0.54
        elif '\xa0' in s:
            value = -0.055 * (n - 1)
        elif '\t' in s:
            value = 0.08
        history[s] = (position, recent + 1)
    elif '\\\\' in s:
        if LATEX.search(tail):
            value = 1.7
        elif ('\\n' in tail[-200:]
              or previous.endswith(('\\"', "\\'"))
              or '"' in s or "'" in s):
            value = -1.25
    elif s == '\n\n' and previous == '<think>':
        value = -0.11
    elif s == '</think>':
        value = 0.077
    all_spacing = all_spacing * math.exp(-0.01) + pure
    return (doc, position + 1, history, all_spacing, s,
            (tail + s)[-300:]), float(value)

