READS = ()


def spelling(text):
    if regex.search(r'\p{Script=Han}', text):
        return ''
    if text.isascii():
        return text.lower()
    converted = anyascii(text).lower()
    # sh/ch transliterations must not invent a letter h.
    if not any(c in 'hHхХهحخハヒフヘホ' for c in text):
        converted = converted.replace('h', '')
