        arabic = bool(regex.search(r'\p{Script=Arabic}', raw))
        if split and arabic:
            value = -6.0 if 'ه' in prev_raw else -2.0
        else:
            value = -2.8 if arabic else -2.0
    elif tail.startswith('arm'):
        value = -3.0 / (1 + 0.8 * (len(tail) - 3))
    elif split and tail.startswith(('em', 'im', 'um', 'erm')):
        value = -2.0 / (1 + 0.5 * max(0, len(tail) - 2))
    elif split and tail.endswith('am') and len(tail) <= 5:
        value = -1.2
    if split and (previous.strip() in ('th', 'ch') or
                  previous.endswith('sch')):
        value *= 0.35
    elif not split and word.rfind('h') > 0:
        before = word[word.rfind('h') - 1]
        if before in 'tcs':
            value *= 0.5
        elif before not in 'aeiou':
            value *= 0.1
        if not s[:1].isspace():
            value *= 0.5
    if s[:1].isspace():
        value *= 0.7
    return carry, value

"""Approximate a detector for short tan-like spelling fragments.

A short an/ann piece joined to t is negative, especially with capitals.
Compact tan/stan, tn, than, and nasalized a after t are also negative.
Some short non-nasal a-consonant pieces after t are mildly positive.
Longer pieces are excluded because spelling alone overpredicts them.
Romanization extends the rules across alphabets; Han tan candidates must
have Mandarin tone 3. UTF-8 fragments are joined before spelling checks.
"""
import codecs
import re
import unicodedata
from functools import lru_cache

import regex
from anyascii import anyascii
from pypinyin import Style, lazy_pinyin

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    # Preserve Arabic written alif, which AnyAscii normally omits.
    return anyascii(text.replace('ا', 'a')).lower()


def nasalized(text):
    nfd = unicodedata.normalize('NFD', text.lower())
    if nfd.startswith(('a\u0303', 'a\u0328')):  # tilde or ogonek
        return True
    return any(
        any(mark in unicodedata.name(ch, '')
            for mark in ('TIPPI', 'BINDI', 'ANUSVARA', 'CANDRABINDU'))
        for ch in text if not ch.isascii()
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, pending = '', b''
    else:
        _, previous, pending = carry
    data = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    s, q = spelling(token), spelling(previous)
    joined = bool(s) and not s[0].isspace()
    short_an = bool(re.fullmatch(r'an(?:[aeiouy]{1,2}s?|s)?', s))
    value = -0.0008

    if joined and q.endswith('t'):
        if nasalized(token):
            value -= 2.57
        elif short_an:
            value -= 4.05
            if previous.endswith('T'):
                value -= 2.34
            if token.isupper():
                value -= 0.94
        elif re.fullmatch(r'ann[a-z]{0,3}', s):
            value -= 3.48
        elif len(s) <= 5 and re.match(r'a[bdfhsz]', s):
            value += 0.41 + (0.52 if len(s) == 2 else 0.0)
        elif s.startswith('n') and len(s) <= 3:
            value -= 0.27
    elif joined and re.search(r't[hy]$', q) and short_an:
        value -= 2.31
    elif joined and q.endswith('ta') and s.startswith('n'):
        value -= 0.23

    word = s.strip()
    if word.isalpha():
        if re.fullmatch(r'[a-z]{0,2}tan[aeiouy]?', word):
            if not regex.search(r'\p{Script=Han}', token) or lazy_pinyin(
                token.strip(), style=Style.TONE3
            ) == ['tan3']:
                value -= 3.13
        elif word == 'tn':
            value -= 0.99
        elif joined and re.fullmatch(r'[a-z]?than', word):
            value -= 1.00
    return (doc, token or previous, pending), float(value)

"""A sparse detector of code boundaries, with a few formatting corrections.

File suffixes, mapping fields, imports, type bodies, and literal openers
receive positive pulses. An opening ``Title:`` heading is especially strong.
Ordinary tokens are quiet; initial words and repeated middle dots are negative.
Only a short, document-local text tail is retained.
"""
import re

READS = ()
CODE_SUFFIXES = {
    '.go', '.rs', '.py', '.js', '.ts', '.java', '.php', '.rb',
    '.cpp', '.hpp', '.cs', '.jar', '.mod', '.sh', '.json',
    '.yml', '.yaml', '.toml', '.conf', '.cfg', '.ini',
}
TEXT_SUFFIXES = {
    '.txt', '.md', '.html', '.css', '.xml', '.vue', '.pdf',
    '.png', '.jpg', '.csv', '.sql',
}
ARCHIVE_SUFFIXES = {'.zip', '.gz', '.tar'}


def predict(token, before, age):
    s = token.strip()
    if token == '\r' and not before.strip('\r'):
        return 10.46  # leading carriage returns, before any visible content
    if token == '··' and before.endswith('··'):
        return -1.44  # a run of middle-dot leaders, not an isolated ellipsis
    if token in CODE_SUFFIXES:
        return 0.0 if re.search(r'\b(?:self|this)$', before) else 0.75
    if token in TEXT_SUFFIXES:
        return 0.35
    if token in ARCHIVE_SUFFIXES:
        return 0.95
    if token in ('.c', '.h', '.r'):
        return 0.3
    if token == '.R':
        return 0.7 if re.search(r'[/\\][\w.-]+$', before) else 0.0
    if token in ('py', 'js', 'go', 'rs') and before.endswith('.'):
        return 1.2

    if s == ':':
        line = re.split(r'\n|\\n', before)[-1]
        if age == 1 and before == 'Title':
            return 8.26
        if re.match(r'\s*(?:\d+\s*)?(?:class|interface)\s+\w+', line):
            return 1.35
        if token != ':' or re.search(r'\b(?:https?|ftp)$', before):
            return 0.0
        if re.search(r'\b(?:def|if|elif|else|for|while|try|except|with)\b', line):
            return 0.0
        # An identifier field inside an open mapping/object, allowing cat -n labels.
        field = re.fullmatch(r'\s*(?:\d+\t\s*)?\w+', line)
        inline = re.search(r'[{,]\s*\w+$', line)
        if (field or inline) and before.count('{') > before.count('}'):
            return 0.65
        return 0.0
    if re.fullmatch(r'\\*["\']:', s):
        if re.search(r'(?:^|[=\n])\{"[^"\n]*$', before):
            return 0.75
        return 0.8 if token.startswith('\\') else 0.2
    if token == ' import' and re.search(r'(?:\b|\\n)from\s+[\w.]+$', before):
        return 1.05
    if s == '{' and re.search(
        r'\b(?:class|interface|struct|enum|namespace)\s+[\w:<>,. \t]+\s*$', before
    ):
        return 1.2
    if s == 'EOF' and re.search(r'<<<?\s*["\']?$', before):
        return 1.8
    if token == '\n' and re.search(r'<<<?\s*["\']?EOF$', before):
        return 1.2
    if s == '#"' and before.endswith('r'):
        return 1.8
    if s in ('"""', "'''"):
        return 2.5 if age == 0 else 0.35
    if re.fullmatch(r'\\+"', token):
        if before.endswith('\\\\') or token.count('\\') >= 2:
            return 1.35
    if '"' in token and token.rstrip().endswith('>') and '\n' in token:
        return 0.65
    if age == 0 and not token.startswith('<|') and any(c.isalpha() for c in s):
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, before = 0, ''
    else:
        _, age, before = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, age)
    return (doc, age + 1, (before + token)[-500:]), value

programs.haiku:
"""layers.1.mlp.down_proj:3800 as a rule-based predictor.

What the component does: it is quiet almost everywhere (typical |activation| about
0.05), and its large positive spikes come at a few code and file-syntax tokens:

- a file-name extension (".go", ".rs", ".py", ".js", ".yaml", ...) right after a file stem,
  as in paths, test names and tool output (about +0.65);
- "import" after "from <module>" in Python (about +1.0);
- "EOF" closing a shell heredoc (about +1.0);
- the colon after a field name in an object literal or config, as in `name: ...`
  or `description: ...` (about +0.13; other colons about +0.05);
- the quote-colon that closes a JSON key, as in `"name":` (about +0.3), and the
  start-of-value quote-colon `:"` (about +0.35);
- an escaped quote `\\"` inside code strings (about +0.3) and a fat arrow ` =>` (about +0.2).

Two rarer spikes: "Title:" in the training examples follows a document break and is about +8,
and a run of middle-dot leader tokens is about -1.4. The first token of each row has no
context, so it gets a small negative baseline (-0.25).

All constants are rough class means measured on training rows; nothing else is learned.
The program keeps no state beyond the current token and the one or two before it.
"""

READS = ()

# File-name extensions: the dot-token that follows a file stem in code, paths and tool output.
FILE_EXTENSIONS = {".py", ".go", ".rs", ".js", ".ts", ".java", ".yaml", ".yml", ".mod", ".jar",
                   ".sh", ".xml", ".vue", ".php", ".json", ".md", ".h", ".c", ".cpp", ".hpp",
                   ".properties", ".zip", ".log", ".toml"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if len(toks) == 1:
        return None, -0.25  # first token of a row: no context
    if cur == ":" and prev == "Title":
        return None, 8.0  # "Title:" label right after a document break
    if cur and set(cur) == {"·"}:
        return None, -1.4  # run of middle dots (leader dots)
    if cur in FILE_EXTENSIONS:
        return None, 0.65
    if cur == " import" and "from" in toks[-4:-1]:
        return None, 1.0  # Python "from x import"
    if cur == "EOF":
        return None, 1.0  # heredoc terminator
    if cur == '":':
        return None, 0.3  # closing quote of a JSON key
    if cur == ':"':
        return None, 0.35
    if cur == '\\"':
        return None, 0.28  # escaped quote inside a code string
    if cur == " =>":
        return None, 0.2
    if cur == ":":
        if prev.strip().isalpha() and prev.strip().islower():
            return None, 0.13  # colon after a lowercase field name, as in object literals
        return None, 0.05
    return None, 0.0

programs.sol:
"""Recognize large mathematical operators, not the arithmetic they perform.

Summation, integration and limits have the largest responses. A TeX backslash
makes the reading unambiguous; ordinary words get a smaller response, depending
on nearby formula/number language. Smaller responses cover infinity, derivatives
and TeX display controls; some relation/layout fragments are negative.
Token fragments are joined for symbols and commands.
The short text buffer and all state restart at document boundaries.
"""
import re
import unicodedata

READS = ()

# Ordinary spelling, mathematical prose, formula spelling, TeX command.
OPERATORS = {
    'sum': (-0.3, 1.2, 7.5, 11.1),
    'prod': (-0.4, 1.0, 7.5, 10.1),
    'int': (-0.3, 0.5, 0.5, 9.7),
    'lim': (-0.3, 0.5, 9.3, 7.4),
    'min': (-0.15, 0.0, 3.5, 5.0),
    'max': (-0.2, 0.0, 3.5, 4.8),
    'sup': (-0.2, 0.5, 3.5, 4.0),
    'inf': (-0.15, 0.0, 3.5, 4.0),
    'dim': (-0.1, 0.0, 2.5, 2.6),
}
SYMBOLS = {
    '∑': 9.5, 'Σ': 6.5, '∏': 9.0, '∐': 3.5,
    '∫': 8.8, '∬': 10.0, '∭': 10.0, '∮': 10.0,
    '⋃': 6.0, '⋂': 6.0, '⋁': 6.0, '⋀': 6.0,
    '∞': 1.1, '∂': 0.8, '∪': 1.7, '∩': 1.0, '∣': 1.5,
}
SYMBOL_BYTES = [(s.encode('utf-8'), v) for s, v in SYMBOLS.items()]
MATH_WORDS = re.compile(
    r'\b(sum|total|prime|divisor|square|root|reciprocal|integral|'
    r'polynomial|coefficient|equation|series|sequence|convergence|formula|'
    r'partition|number|dimension|variable|vector|binomial|term)s?\b', re.I
)
CODE_WORDS = re.compile(
    r'(?<!\\)\b(return|def|printf|public|const|import|self)\b|'
    r'(?<!\\);|\b(for|while|if)\s*\(|->|[A-Za-z_]{2,}\.[A-Za-z_]'
)
COMMAND = re.compile(r'\\([A-Za-z]*)$')
FORMULA_END = re.compile(r'[=+−<({\[\-]\s*$')


def math_context(before):
    return (any(c in before for c in '$^=∑∫')
            or bool(MATH_WORDS.search(before))
            or any('GREEK' in unicodedata.name(c, '') for c in before))


def predict(token, raw, before, byte_tail):
    word = token.strip()
    joined = byte_tail + raw
    if any(b >= 128 for b in raw):
        for symbol, value in SYMBOL_BYTES:
            if joined.endswith(symbol):
                if symbol == '∫'.encode() and token == '�':
                    return 10.0
                return value
    match = COMMAND.search(before) if word.isalpha() and token == word else None
    command_prefix = match.group(1) if match else None
    if command_prefix is not None:
        command = command_prefix + word
        if not command_prefix and word in OPERATORS:
            return OPERATORS[word][3]
        if command in {'iint', 'iiint', 'oint', 'dint'} and word == 'int':
            return 11.5
        if command in {'bigvee', 'bigwedge', 'bigcup', 'bigcap', 'coprod'}:
            return 6.5
        if command == 'infty':
            return 2.1
        if word == 'unders':
            return 5.0
        if word in {'display', 'displaystyle', 'operator', 'operatorname'}:
            return 1.8
        if not command_prefix:
            if word == 'left':
                return 0.9
            if word == 'right':
                return 0.2
            if word in {'big', 'Big', 'bigg', 'Bigg', 'partial', 'dot', 'cup'}:
                return 0.9
            if word in {'map', 'impl', 'there', 'set', 'back', 'var'}:
                return -2.6
            if word in {'ld', 'up'}:
                return -1.8
            if len(word) == 1 and word.islower() and word not in 'ntr':
                return -1.0
        if command in {'textup', 'mathrel', 'mathnormal'}:
            return -6.8 if command == 'textup' else -2.8
        if command in {'mathcal', 'boldsymbol'}:
            return 0.6
        if command in {'therefore', 'implies'}:
            return 0.7
    lower = word.lower()
    if lower in OPERATORS:
        values = OPERATORS[lower]
        if lower in {'min', 'max'} and before.rstrip().endswith('arg'):
            return 5.5
        # Interior fragments and programming identifiers are not big operators.
        if word.isupper() or CODE_WORDS.search(before[-70:]):
            return values[0]
        if token == word and before and before[-1].isalpha():
            return values[0]
        math = math_context(before)
        if lower in {'int', 'min', 'max', 'inf', 'sup', 'dim'}:
            if lower == 'dim' and math and word.islower():
                return 2.5
            explicit = any(c in before for c in '$^∑∫')
            explicit = explicit or any(
                'GREEK' in unicodedata.name(c, '') for c in before
            )
            return values[2] if explicit and FORMULA_END.search(before) else values[0]
        if lower == 'lim':
            formula = FORMULA_END.search(before)
            label = re.search(r'\(\d+(?:\.\d+)*\)\s*$', before)
            return 9.0 if formula or label else values[0]
        if FORMULA_END.search(before):
            return values[2]
        if math and before.endswith('\n\n'):
            return 4.5
        return values[1] if math else values[0]
    if lower in {'integral', 'integr', 'infinity', 'product', 'union', 'series'}:
        math = math_context(before)
        if lower == 'infinity':
            return 0.7
        if lower == 'integral':
            return 1.2
        if lower == 'integr':
            return 0.3
        if lower == 'product':
            if math and FORMULA_END.search(before) and not CODE_WORDS.search(before):
                return 5.5
            return 1.1 if math else -0.2
        if lower == 'union':
            return 0.8 if math else -0.1
        return 1.2 if re.search(
            r'\b(alternating|geometric|harmonic|power|Taylor|Fourier|Laurent)\s*$',
            before, re.I
        ) else -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, byte_tail = '', b''
    else:
        _, before, byte_tail = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    value = predict(token, raw, before, byte_tail)
    return (doc, (before + token)[-160:], (byte_tail + raw)[-8:]), float(value)

"""A lexical 'liu / leave behind' detector, not a departure classifier.

Strong responses mark 留, its common compounds, and the spelling Liu (even
across token boundaries). Smaller responses mark English leave/lack/remain
words. A few immediate continuations of 留 inherit part of its response.
The byte rules recognize incomplete UTF-8 spellings of 留. Most other tokens
get nearly zero. Document starts have a negative baseline except for
question openings; an initial end-of-text marker gets a stronger negative.
"""

READS = ()


def lexical(token, before):
    word = token.strip()
    lower = word.lower()
    if '留' in word:
        if word == '留':
            return 9.0
        if word == '不留':
            return 7.0
        if word.startswith('留下'):      # leave behind
            return 4.8 if word.endswith('了') else 6.0
        if '留学' in word or '留學' in word:  # study abroad
            return 5.5 if len(word) == 2 else 4.7
        if word.startswith('留言'):      # leave a message
            return 3.0 if len(word) == 2 else 1.0
        if word.startswith(('拘留', '留意', '留守')):
            return 0.5
        if word.startswith('留住'):      # retain
            return 2.0
        if word.startswith('留'):
            return 3.5
        if word.startswith('保留'):      # preserve
            return 1.1
        return 2.3
    if word in ('刘', '劉'):
        return 2.8 if word == '刘' else 3.5
    if word == '流':
        return 0.4

    # The response is stronger when a token completes a split spelling.
    # Split spellings must be contiguous, never joined across whitespace.
    previous = before.lower() if token and not token[0].isspace() else ''
    l_start = len(previous) < 2 or not ('a' <= previous[-2] <= 'z')
    li_start = len(previous) < 3 or not ('a' <= previous[-3] <= 'z')
    if previous.endswith('l') and l_start and lower.startswith('iu'):
        return 10.0 if lower == 'iu' else 3.5
    if previous.endswith('li') and li_start and lower.startswith('u'):
        return 9.0 if all(c in 'aeiouy' for c in lower) else 3.5
    if lower == 'liu':
        return 3.1
    if previous.endswith('li') and li_start and lower == 'ou':
        return 3.5
    if previous.endswith('le') and lower == 'u':
        return 1.8 if before.endswith('Le') else 0.3
    if lower == 'lưu' or (lower == 'ưu' and previous.endswith('l')):
        return 4.0
    if lower in ('leave', 'leaving', 'leaves', 'left'):
        if lower == 'left' and not token.startswith(' '):
            return -0.04
        value = {'leave': 0.52, 'leaving': 0.40,
                 'leaves': 0.29, 'left': 0.14}[lower]
        return value + (0.15 if word[0].isupper() and lower != 'left' else 0)
    if previous.endswith('le') and lower.startswith('av'):
        return 0.7
    if lower in ('lack', 'lacks', 'lacking', 'lacked'):
        return 0.36
    if lower in ('remain', 'remains', 'remained', 'remaining',
                 'release', 'released', 'releasing', 'missing', 'without'):
        return 0.15
    return -0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    history, last = (b'', '') if start else carry[1:]
    raw = prefix.token_bytes[-1]
    before = history.decode('utf-8', 'ignore')
    joined = history + raw
    token = joined.decode('utf-8', 'ignore')[len(before):]
    value = lexical(token, before)

    # A split 留 can already be recognized before the character is complete.
    if history.endswith(b'\xe7') and raw == b'\x95':
        value = 9.5
    elif history.endswith(b'\xe7\x95') and raw == b'\x99':
        value = 12.0
    elif last == '留' and value < 0.2:
        if token.startswith('下'):
            value = 5.5                 # leave behind
        elif token.startswith(('学', '學')):
            value = 5.8                 # study abroad
        elif token.startswith('了'):
            value = 3.8                 # completed act of leaving
        elif token.startswith(('个', '個', '有', '住')):
            value = 2.5
        elif token.startswith('着'):
            value = 2.0

    if start and value == -0.005:
        word = token.strip().lower()
        if word == '<|endoftext|>':
            value = -3.66
        elif word in ('what', 'how'):
            value = 0.7
        elif word in ('who', 'why', 'where', 'when', 'can',
                      'do', 'does', 'is', 'are'):
            value = 0.3
        else:
            value = -0.30
    return (doc, joined[-32:], token.strip()), value

programs.haiku:
"""layers.1.mlp.down_proj:3803 -- a detector for the syllable "liu" (留 / 刘 / Liu).

The component writes a large value into the residual stream when the current
token is part of the Mandarin syllable "liú" as written in Chinese characters or
in Latin letters:

  * the character 留 (stay / leave behind), strongest on the bare character
    (留 ~8.5), weaker on words built from it (留下, 留学, 留言, 停留 ~4);
  * the surname 刘 / 劉 / 琉 and the names Liu / lưu, ~3.5;
  * the Latin spelling of the syllable split across tokens: "iu" right after a
    standalone "L" (L|iu, ~9), and "u" / "ou" right after "Li" (~5).

Everything else predicts 0. The program reads only the newest token and the one
before it (within the same document), so it needs no carried state.
"""

READS = ()

LIU_NAMES = {"刘", "劉", "琉", " Liu", "Liu", " lưu", "ưu"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2]
    stem = before.strip(" /\t.,-\"'(").lower()
    if token == "留":
        value = 8.5
    elif "留" in token:
        value = 4.0
    elif token in LIU_NAMES:
        value = 3.5
    elif stem == "l" and token == "iu":
        value = 9.0
    elif stem == "li" and token in ("u", "ou"):
        value = 5.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A weak document-onset response, plus code and dialogue delimiters.

The first token is usually negative, less so for numbers or single capitals;
a leading hash is positive. Away from the onset, most text is near zero.
Bare import tokens and explicit tool/thinking tags get small signed pulses.
This is a coarse approximation, not a model of all lexical variation.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        if word == '#':
            value = 0.44
        elif word.isdigit():
            value = -0.20
        elif len(word) == 1 and word.isalpha() and word.isupper():
            value = -0.08
        elif len(word) <= 1 and not token.isspace():
            value = -0.28
        else:
            value = -0.37
    elif token == 'import':
        value = 0.12
    elif token in ('<tool_call>', '</tool_call>', '</think>'):
        value = 0.085
    elif token in ('</tool_response>', '<think>'):
        value = -0.11
    else:
        value = -0.0015
    return None, value

"""Approximate a mainly tab-sensitive response.

A standalone tab is strongest, especially after a printed source-line number.
Tabs bundled with whitespace or text, and later tabs on a line, are weaker.
Document starts instead receive a negative baseline, stronger for initial tabs.
There are also rules for nonbreaking spaces (stronger after a dash), the chat
opening marker, and the strongly negative colon in a document-opening Title:.
Other tokens are zero away from document starts. State keeps the document
position and the last 100 characters of the current line, not the whole prefix.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, line = 0, ''
    else:
        _, position, line = carry
    token = prefix.token_strings[-1]
    numbered = line.strip().isdigit()
    earlier_tab = '\t' in line
    value = -0.35 if position == 0 else 0.0
    if '\t' in token:
        tabs = token.count('\t')
        spaces = token.count(' ')
        if position == 0:
            if token == '\t':
                value = -6.88
            elif spaces:
                value = -2.4 / (1 + spaces / 4)
            else:
                value = -2.7
        elif token == '\t':
            if earlier_tab:
                value = 1.1 if numbered else 0.9
            elif numbered:
                value = 2.35
            elif line.strip():
                value = 2.0
            else:
                value = 1.55
        elif token.isspace():
            if '\n' in token or '\r' in token:
                value = 1.32 if numbered and tabs == 1 else 0.85
                if token.count('\n') > 1:
                    value = 0.8
            elif spaces:
                value = max(-0.15, 1.03 - 0.17 * spaces)
                if token.startswith(' '):
                    value -= 0.4
            else:
                value = max(0.85, 1.2 - 0.05 * tabs)
                value += 0.4 * numbered - 0.15 * earlier_tab
        else:
            value = 0.75 if numbered else 0.5
            if earlier_tab:
                value = 0.1
    elif token == '\xa0':
        value = 1.5 if line.rstrip().endswith(('–', '—')) else 0.1
        if position == 0:
            value = -0.78
    if position == 0 and token == '<|im_start|>':
        value = -0.69
    if position == 1 and token == ':' and line == 'Title':
        value = -13.06
    line = (line + token).rsplit('\n', 1)[-1][-100:]
    return (doc, position + 1, line), value

"""A sparse spelling heuristic for split in-/im-/int-like fragments.

Negative responses chiefly mark a short preceding fragment continued without
whitespace: in + consonant, im + labial, and int + e/o/u. Cyrillic in has a
stronger response. Word frequency discounts likely complete English words.
There are also small rules for isolated i, integer-type digits, and kana forms.
The separate phrases 'in to', 'in mind', and 'in itself' have their own scores.
Document starts receive a small positive offset.
This approximates the spelling pattern, not the component's full context effects.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def spelling(s):
    n = unicodedata.normalize('NFKD', s.casefold())
    n = ''.join(c for c in n if not unicodedata.combining(c))
    word = re.sub(r'^[^\w]+', '', n)
    return n, word


@lru_cache(maxsize=20000)
def common_word(word):
    return zipf_frequency(word, 'en') >= 4.5


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    n, word = spelling(previous)
    current, _ = spelling(s)
    value = 0.18 if first or previous == '<|endoftext|>' else 0.0

    if previous == ' in' and s == ' to':
        value -= 4.0
    if word == 'in':
        if current == ' mind':
            value += 1.73
        elif current == ' itself':
            value += 1.16

    if current and current[0].isalpha() and len(word) <= 5:
        ch = current[0]
        if n.endswith('in') and ch in 'bcdfghjklmnpqrstvwxyz':
            value -= 0.37
            if ch in 'fsvt':
                value -= 0.54
            if word != 'in' and common_word(word):
                value += 0.30
        if n.endswith('im') and ch in 'pbm':
            value -= 0.73
        if n.endswith('int'):
            if ch == 'e':
                value -= 0.55
            elif ch in 'ou':
                value -= 0.33
        if n.endswith(('inf', 'ins', 'ind')) and ch in 'aeiou':
            value -= 0.20
        if word in ('i', 'и', 'і') and ch in 'nmнм':
            value -= 0.33
        if n.endswith('ин') and ch not in 'аеёиоуыэюяіїє':
            value -= 0.84
            if ch == 'ф':
                value -= 2.02
            elif ch in 'тд':
                value -= 0.99
        if word == 'им' and ch in 'пбм':
            value -= 0.89
        if word.endswith('イン'):
            value -= 0.84
        if word == 'い' and current.startswith('き'):
            value -= 1.64

    if current.isdigit() and len(word) <= 5:
        if n.endswith('int'):
            value -= 0.59
        elif word == 'i':
            value -= 0.47
    return (doc, s), value

"""A short-symbol boundary detector.

Numbers, single letters, Greek letters and short capital abbreviations get a
positive response when they end, especially before a spaced separator. The
response is smaller inside words, after long numerals, and at sentence ends.
A letter followed by a space and a number also gives a response. Words at
a row/document start have a separate onset response.
"""
import re
import unicodedata

READS = ()
GREEK_NAMES = set('alpha beta gamma delta epsilon zeta eta theta iota kappa '
                  'lambda mu nu xi omicron pi rho sigma tau upsilon phi chi '
                  'psi omega'.split())
RELATIONS = set('is are was were be equals equal to of in for by as from with '
                'on at into'.split())


def single_letter(s):
    return len(s) == 1 and s.isascii() and s.isalpha()


def response(p, s, pp, run):
    w, q = p.strip(), s.strip()
    letter = single_letter(w)
    capitals = w.isascii() and w.isalpha() and w.isupper() and len(w) <= 5
    greek = len(w) == 1 and 'GREEK' in unicodedata.name(w, '')
    simple = not w or w.isdecimal() or letter or capitals or greek
    simple = simple or w.lower() in GREEK_NAMES
    if not simple:
        if re.fullmatch(r'[\(\[\{\$][a-zA-Z]', w):
            return 0.38
        return 0.04 if single_letter(pp.strip()) else -0.004

    # Rejoin a token fragment to the preceding token before measuring the word.
    word = re.search(r'[a-zA-Z]+$', p if p[:1].isspace() else pp + p)
    length = len(word[0]) if word else 0
    if q.isdecimal():
        if length == 1:
            return 0.48
        return 0.37 if single_letter(pp.strip()) else -0.009
    if p[-1:].isspace():
        return -0.009
    if q.isalpha() and len(q) > 1:
        if not p:
            return 0.55
        if q in RELATIONS:
            return 0.34
        return 0.26 if run == 1 else 0.05
    if q and (q in '.?!' or (len(q) < 5 and q[-1] in '.?!')):
        return 0.06
    if length > 2:
        return 0.04
    if run >= 4:
        return 0.09
    if run == 3:
        return 0.11 if '\t' in s else 0.38
    if s[:1].isspace():
        if letter and w.isupper():
            return 0.95
        article = w in ('a', 'I') and p.startswith(' ')
        if letter and not article and not q:
            return 0.26
        return 0.29 if '\n' in s else 0.64
    if '\n' in s and q:
        return 0.08
    if p[:1].isalpha() and pp[-1:].isalpha():
        return 0.11
    if capitals and not letter and s[:1].isalnum():
        return 0.01
    return 0.41


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p = pp = ''
        run = 0
    else:
        _, p, pp, run = carry
    value = response(p, s, pp, run)
    run = run + 1 if s.isdecimal() else 0
    return (doc, s, p, run), value

