"""Candidate C: fires on the token right after a number or a one-letter variable,
and at the first token of each document."""
READS = ()

MATH_MARKS = set("()[]{}|=+-*/^_<>×±≤≥≈→⇒∈~$\\")
SUPERSCRIPTS = set("⁰¹²³⁴⁵⁶⁷⁸⁹₀₁₂₃₄₅₆₇₈₉")


def _core(s):
    return s.strip()


def _is_digit(s):
    c = _core(s)
    return c != "" and all(ch.isdigit() for ch in c)


def _is_variable(s):
    c = _core(s)
    return len(c) == 1 and c.isascii() and c.isalpha()


def _is_word(s):
    c = _core(s)
    return len(c) > 1 and c.isalpha()


def _is_math(s):
    return _is_digit(s) or _is_variable(s) or any(ch in MATH_MARKS or ch in SUPERSCRIPTS for ch in s)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.39  # first token of a document
    if any(ch in SUPERSCRIPTS for ch in cur):
        return None, 0.74  # superscript digit: x²
    prev = toks[-2]
    if _is_digit(prev) or _is_variable(prev):
        if _is_digit(prev) and _is_digit(cur):
            return None, 0.0  # inside a number
        if _is_word(cur):
            return None, 0.09  # "a is", "2 squared": words after a number/variable
        if _is_math(cur):
            return None, 0.43  # operator, bracket, or variable right after a number/variable
        return None, 0.26  # space or punctuation after a number/variable
    return None, 0.0

