"""Approximate a front-vowel/labial spelling signal in word fragments.

High-activation examples often split words around if, iv, or a vowel
followed by f/v/w/b. Transliteration lets the same spelling rules cover
several scripts. Scores depend on fragment length and nearby letters;
recognized -ive adjective endings and divisibility words are weaker.
This is a spelling-based approximation, not a token lookup table.
State is the last 40 letters of the word, reset at nonletters/documents.
"""
import re
from functools import lru_cache
from anyascii import anyascii
import wordnet

READS = ()

# Vowel-labial pair: base, extra letters after the pair, length > 4.
PAIRS = {
    'iv': (1.264, -0.559, -0.526),
    'if': (1.260, -0.656, -0.465),
    'iw': (1.236, -1.072, 0.),
    'ib': (0.186, 0., 0.),
    'ew': (0.214, 0., 0.),
    'ef': (0.200, 0., 0.),
    'ow': (0.122, 0., 0.),
    'uw': (0.209, 0., 0.),
}
# Across tokens: score after a lone vowel / a vowel in a longer word.
BOUNDARIES = {
    'if': (0.772, 0.366),
    'iw': (0.896, 1.662),
    'ib': (0.268, 0.268),
    'iv': (1.084, 1.817),
    'yv': (1.645, 1.645),
    'yw': (1.116, 2.169),
    'ew': (0., 0.827),
    'eb': (-0.241, 0.134),
    'ev': (0.411, 0.411),
}
FRONT_BEFORE = {
    'f': 0.434,
    'v': 0.415,
}
TS_BEFORE = {
    'f': -0.214,
    'v': -0.204,
}


@lru_cache(16384)
def spelling(text):
    return anyascii(text).lower().replace('ph', 'f')


def word_tail(text):
    match = re.search(r'[a-z]+$', text)
    return match.group()[-40:] if match else ''


@lru_cache(16384)
def activation(text, word):
    z = spelling(text)
    value = -1.364 if 'divisib' in z else 0.
    if not z or not word or not text[0].isalpha():
        return value

    # A vowel-labial pair near the beginning of the newest token.
    match = re.search(r'[eiyaou][fvwb]', z[:4])
    if match:
        vowel, labial = match.group()
        vowel = 'i' if vowel == 'y' else vowel
        base, extended, longer = PAIRS.get(vowel + labial, (0., 0., 0.))
        value += base
        if match.end() < len(z):
            value += extended
        if len(z) > 4:
            value += longer
        if match.start():
            value -= 0.108
        else:
            if word[-1] in 'eiy':
                value += FRONT_BEFORE.get(labial, 0.)
            if word[-1] in 'ts':
                value += TS_BEFORE.get(labial, 0.)
            if labial == 'v':
                if word[-1] == 'y':
                    value += 0.990
                if word.endswith(('z', 'zh', 'sh', 'ch')):
                    value += 0.444

    # Distinguish an adjective's -ive from a name such as Clive.
    if z.startswith('ive'):
        complete = word_tail(word + z)
        ending = re.search(r'iv(?:e|es|a|o|i|as|os|ely)?$', complete)
        if ending:
            candidate = complete[:ending.start()] + 'ive'
            if 'adjective' in wordnet.parts_of_speech(candidate):
                value -= 0.641

    # A short labial fragment immediately following a front vowel.
    if z[0] in 'fvwb' and len(z) <= 3 and word[-1] in 'eiy':
        labial = z[0]
        alone, attached = BOUNDARIES.get(word[-1] + labial, (0., 0.))
        value += attached if len(word) >= 2 else alone
        if len(z) == 1:
            if labial == 'f':
                value += 0.940
            elif labial == 'w':
                value += 0.663
        if labial == 'w' and ord(text[0]) > 127:
            value -= 1.357

    if len(word) > 1 and word[-2] in 'eiy' and word[-1] in 'fvwb':
        if len(z) <= 3 and z[0] in 'aeiouy':
            value += 0.214
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == document else ''
    text = prefix.token_strings[-1]
    value = activation(text, word)
    return (document, word_tail(word + spelling(text))), float(value)

"""A spelling-sensitive 上 ('on/up') detector, not a general up/down axis.

The strongest negative values mark separate 上, especially after a word
with a verb reading, and resultative compounds ('put on', 'go onto', etc.).
Fused words and Japanese inflections are weaker. It also recognizes some
transliterations and positive son/up fragments. Other text is near zero.
Only an 80-character history is retained, reset at document boundaries.
"""
import regex
import cedict

READS = ()

# Verbs commonly taking 上 as a result/directional complement.
RESULT_VERBS = frozenset('走踏戴穿爱愛带帶患遇送配登赶趕套爬')


def strength(text, history, previous):
    s = text.strip()
    if '上' in s:
        japanese = regex.search(r'\p{Hiragana}|\p{Katakana}', history + s)
        if japanese:
            if s == '上':
                return -2.64
            if regex.search('上[がげ]', s):
                return 0.06
            return -1.7 if s == '上の' else -0.65
        if s == '上':
            verb = bool(previous) and any(
                g.startswith('to ') for g in cedict.glosses(previous.strip())
            )
            return -4.8 if verb else -3.75
        if '上海' in s:
            return -1.27
        if '上午' in s:
            return -2.3
        if s in ('晚上', '早上'):
            return -2.44
        if '以上' in s:
            return -0.95
        if s == '之上':
            return -1.69
        if s.startswith('上'):
            return -4.14 if len(s) == 2 and s[1] in '的了有' else -0.27
        if s.endswith('上'):
            if len(s) == 2 and s[0] in RESULT_VERBS:
                return -4.93
            return -2.74 if len(s) == 2 else -2.08
        return -1.13
    # Sometimes a compound is split after 上: 上海, 上午, 上的.
    if s in ('海', '午', '的') and history.rstrip().endswith('上'):
        return -3.37
    if s == '尚':
        return -2.04
    if s == '상':
        return -1.3
    if s == '下午':
        return -0.79
    if s.lower() == 'shanghai':
        return -2.05
    if text == 'ang' or s == 'ượng':
        word = regex.search(r'[A-Za-z]+$', history)
        lead = word[0].lower() if word else ''
        if text == 'ang' and lead.endswith('sh'):
            return -8.4  # Completion of romanized Shang.
        if s == 'ượng' and lead.endswith('th'):
            return -5.5  # Vietnamese thượng: upper/above.
    if s.lower() == 'thượng':
        return -5.5
    if text in ('son', 'sons'):
        return 0.4
    if text == 'сон':
        return 1.09
    if text == 'up':
        return 0.52
    if text == 'UP':
        return 1.46
    if s in ('uppercase', '-upper'):
        return 0.8
    if s == '↑':
        return 1.93
    if text == '+':
        return -0.156
    if s == 'top':
        return -0.24
    if text == ' on':
        return -0.03
    return -0.0034


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    history = '' if start else carry[1]
    previous = '' if start else prefix.token_strings[-2]
    value = strength(text, history, previous) + (0.275 if start else 0.0)
    return (doc, (history + text)[-80:]), float(value)

"""A document-onset response, coarsely calibrated by the opening token.

The opening token, including an initial run of exact repetitions, receives a
response; subsequent tokens receive zero. Document boundaries restart it.
Digits, whitespace, punctuation, currency signs, Latin capitalization, and a
few English grammatical words determine its level. This captures the onset
pattern, but not the component's full word-by-word amplitude variation.
"""
READS = ()


def onset(text):
    word = text.strip()
    spaced = text.startswith(' ')
    if text.startswith('<|'):
        return 0.6
    if not word:
        return 3.8 if any(c in text for c in '\n\r\t') else 0.1
    if word.isdecimal():
        return -0.58
    if any(c in word for c in '$£€¥₹'):
        return 10.0
    if word.isascii() and word.isalpha():
        lower = word.lower()
        if lower in {'a', 'an', 'the'}:
            if spaced and word == 'a':
                return -8.3
            if not spaced and word.istitle():
                return -1.3
            return 2.4
        if spaced and lower in {'am', 'is', 'are', 'was', 'were'}:
            return -2.4
        if spaced and lower == 'to':
            return 8.5
        if spaced and lower == 'of':
            return 6.6
        if word.istitle():
            return 4.7 if spaced else 3.3
        return 2.8
    if not any(c.isalnum() for c in word):
        if all(c in '.,;:!?' for c in word):
            return -0.2 if not spaced else 3.3
        if '\n' in text or '\r' in text:
            return 3.8
        return 3.3 if spaced else 2.8
    return 2.7 if spaced else 1.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    else:
        carry = (doc, carry[1], carry[2] and token == carry[1])
    value = onset(prefix.token_strings[-1]) if carry[2] else 0.0
    return carry, value

"""Approximate the component's document-opening pulse.

The large responses in training were mostly opening formatting/code tokens,
and runs repeating the identical opening token. Once a different token has
arrived, predict almost zero. Opening prose is approximated by case, script,
and English function-word classes, not a table of individual words. Short opening comment/template continuations also have pulses. Later
exceptions handle a byte-order mark and the web phrase "This preview shows
page(s)".
"""
import regex

READS = ()
FUNCTION_WORDS = frozenset(
    'the a an of to in on at by for with from and or but if as is are '
    'was were be been that this not'.split()
)
PRONOUNS = frozenset(
    'i you he she it we they my your his her our their me us them'.split()
)
# Source-file and markup opening delimiters.
OPENING_MARKS = {
    '//\n': 13.05,
    '//': -0.91,
    '/*': 1.63,
    '<?': 1.51,
    ';': 1.41,
    '{': -0.84,
    '(': 0.69,
    '>`\n': 2.22,
}


def opening_value(text):
    word = text.strip()
    if text in OPENING_MARKS:
        return OPENING_MARKS[text]
    if text in {'\r', '\x00'}:
        return 6.94 if text == '\x00' else 7.15
    if text == '\u200e':
        return 2.14
    if word == '•':
        return 4.83 if text.startswith(' ') else 5.77
    if word == '>':
        return 2.96 if text.startswith(' ') else 1.41
    if len(text) >= 4 and set(text) == {'\\'}:
        return 3.17
    if word in {'»', '«'}:
        return 4.24 if text.startswith(' ') else 2.69
    if word == '×' and '\n' in text:
        return 3.72
    if text and set(text) == {'·'} and len(text) > 1:
        return 2.98
    if text and set(text) == {'^'} and len(text) > 1:
        return 2.05
    if word and set(word) == {'#'}:
        return 1.41 * len(word) if len(word) <= 2 else 1.51
    if text.startswith('/*'):
        return 0.85
    if word in {'"""', "'''"}:
        return 1.5
    if text.startswith('<|'):
        return 3.36 if text == '<|endoftext|>' else 0.1
    if text.isspace():
        if '\xa0' in text:
            return 3.09 if text == ' \xa0' else 1.8
        if text == '\t':
