        return 4.05 if text == 'int' else 3.39
    if text in {'class', 'def'}:
        return 2.75
    if text == 'package':
        return 1.31
    if text == 'import':
        return -0.87
    if '\ufffd' in text:
        return -1.05
    if word.isdecimal():
        return 0.26
    if word.lower() in PRONOUNS:
        return 0.5
    if word.lower() in FUNCTION_WORDS:
        return 0.07
