import re

READS = ()

LINE_COMMENT_NEWLINE = {"//\n"}
STRONG = {"<!", "\r", "\x00", "•", "void"}
MEDIUM = {"int", "char", "string", "class", "def", "##", "<|endoftext|>", "\\\""}
CODE_OPENERS = {
    "#", "###", "####", "#ifndef", "/*", "/**", "/*\n", "\"\"\"", "\"\"\"\n",
    "<?", "package", "private", "const", "function",
}
SLIGHTLY_NEGATIVE = {"import", "//", "A", "B", "R", "M", "S"}


def first_token_value(tok):
    if tok in LINE_COMMENT_NEWLINE:
        return 13.0
    if tok in STRONG:
        return 6.0
    if tok in MEDIUM:
        return 2.5
    if tok in CODE_OPENERS:
        return 1.5
    if tok in SLIGHTLY_NEGATIVE:
        return -0.8
    if re.fullmatch(r"\d+", tok):
        return 0.3
    if re.fullmatch(r"[A-Z][a-z]+", tok):
        return 0.5
    return 0.3


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        first, run = tok, True
    else:
        first, run = carry[0], carry[1] and tok == carry[0]
    value = first_token_value(first) if run else 0.0
    return (first, run), float(value)

