import unicodedata

READS = ()

# Responses to a few short m-bearing spellings.
M_FRAGMENTS = {
    'damit': 6.5,
    'imit': 2.0,
    'mitt': 2.0,
    'mites': 2.0,
    'mang': 2.8,
    'mv': 1.8,
    'mood': -6.0,
    'moody': -4.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    previous_was_first = False if new_document else carry[2]
    token = prefix.token_strings[-1]
    piece = token.strip().lower()
    prev = previous.lower()
    value = M_FRAGMENTS.get(piece, -0.003)

    if piece == 'mit':
        boundary = not previous or not previous[-1:].isalpha()
        value = 4.1 if token[:1].isspace() or boundary else 2.0
        if not boundary and not token[:1].isspace():
            last_letter = unicodedata.normalize('NFD', previous[-1]).lower()[0]
            if last_letter in 'eio':
                value = 0.4
    elif piece == 'mob' and prev.endswith('b') and token[:1].isalpha():
        value = -1.7
    elif piece == 'manner':
        value = -5.7 if prev.strip() == 'all' else -0.4
    elif len(piece) >= 2 and set(piece) == {'·'}:
        value = -1.15

    # The same short spelling fragments can straddle a token boundary.
    if token[:1].isalpha() and prev.endswith('m'):
        isolated_m = prev.strip() == 'm'
        if piece == 'it':
            if prev.strip() in ('com', 'rem', 'perm'):
                value = 0.8
            elif prev.endswith(('wom', '-m')):
                value = 8.0
            else:
                value = 4.0
        elif piece == 'ith':
            lower_m = isolated_m and previous.endswith('m')
            value = 9.5 if lower_m else 5.0
        elif piece == 'ite':
            value = 9.0 if isolated_m else 3.5
        elif piece in ('its', 'ites', 'itt', 'itten'):
            if isolated_m:
                value = 8.0 if piece in ('its', 'ites') else 4.0
            else:
                value = 2.0
        elif piece.startswith('oo'):
            value = -6.5 if piece == 'ood' else -2.0
        elif piece in ('ow', 'ows', 'owed', 'owing'):
            value = -4.5
        elif piece in ('ew', 'ello', 'ellow'):
            value = -3.8
        elif piece.startswith('y') and len(piece) <= 3:
            value = 0.5 if piece == 'y' else 2.6
        elif piece == 'arm':
            value = 3.4
        elif piece in ('frac', 'ro', 'row'):
            value = -8.0 if piece == 'row' else -3.6
        elif piece == 'unes' and prev.endswith('comm'):
            value = -4.5
        elif piece in ('ie', 'ide', 'id'):
            value = 0.5
        elif piece in ('ee', 'if', 'uth', 'ang', 'idd'):
            value = 1.4
        elif piece in ('umps', 'iable'):
            value = -3.2
    elif token[:1].isalpha() and prev.endswith('mo') and piece.startswith('o'):
        value = -4.0

    # The same m + it spelling in Cyrillic.
    if prev.endswith('м') and piece == 'ит':
        value = 7.0

    if token == ':' and previous == 'Title' and previous_was_first:
        value = 7.34
    first = new_document or previous == '<|endoftext|>'
    return (doc, token, first), value

