"""Second member of a coordinated pair or list, read off the previous token."""

READS = ()

FUNCTION_WORDS = {"the", "a", "an", "of", "in", "on", "at", "to", "for", "with", "by", "from",
                  "as", "is", "was", "be", "are", "it", "i", "he", "she", "we", "they", "you",
                  "his", "her", "its", "their", "our", "my", "your", "this", "that", "these",
                  "those", "not", "so", "if", "then", "than", "but"}

# how strongly a word after each joiner tends to be a parallel item
JOINERS = {"and": 0.4, "or": 0.4, "+": 0.8, "&": 0.25, "und": 0.3, "和": 0.45,
           "与": 0.4, "или": 0.2, "и": 0.1, "、": 0.2, "vs": 0.7, "–": 0.2, "−": 0.2}
COMMA = 0.1


def step(carry, prefix, upstream):
    ids, docs, toks = prefix.token_ids, prefix.document_ids, prefix.token_strings
    if len(ids) < 2 or docs[-2] != docs[-1]:
        return None, 0.0
    word = toks[-1].strip()
    if not word.isalpha() or word.lower() in FUNCTION_WORDS:
        return None, 0.0
    before = toks[-2].strip()
    if before in JOINERS:
        value = JOINERS[before]
    elif before == ",":
        value = COMMA
    else:
        return None, 0.0
    # a pair of words sharing an ending ("upward and downward") is a stronger parallel
    if len(ids) >= 3 and docs[-3] == docs[-1]:
        earlier = toks[-3].strip()
        if len(word) > 2 and len(earlier) > 2 and earlier[-2:].lower() == word[-2:].lower():
            value *= 2.0
    return None, float(value)

