"""Approximate a token-sensitive spelling-fragment response.

Short ut/lut-like pieces usually contribute negatively; their preceding
letters matter. A few str-/tr- stem completions contribute positively,
as do 'in' and 'forth' after put/putting. Longer suffixes such as -ution
are deliberately excluded. This leaves much of the background response
unexplained. State tracks spelling across tokens, not future word endings.
"""
READS = ()

# Stem, possible endings of the spelling seen SO FAR, response.
# These are word families, not a vocabulary-token lookup.
FAMILIES = (
    ('strut', ('', 's', 't', 'ter', 'ters', 'ted', 'ting'), 6.49),
    ('strid', ('', 'e', 'es', 'er', 'ers', 'ing', 'ent'), 5.01),
    ('strath', ('',), 4.46),  # Scottish place-name stem
    ('stradd', ('', 'le', 'les', 'led', 'ling'), 3.10),
    ('striv', ('', 'e', 'es', 'ing'), 1.33),
    ('tread', ('', 's', 'ed', 'ing'), 3.44),
    ('trot', ('', 's', 't', 'ter', 'ters', 'ted', 'ting'), 3.12),
    ('glut', ('', 's', 'ton', 'tony'), 1.27),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, old_word = '', ''
    else:
        _, previous, old_word = carry
    s = prefix.token_strings[-1].lower()
    c = s.lstrip()
    joins = bool(s and s[0].isalpha() and previous
                 and previous[-1].isalpha())
    old = old_word if joins else ''
    word = old + s if joins else c
    value = 0.0

    # Very short pieces, not longer derivational suffixes.
    if c.startswith('ut') and len(c) <= 4:
        value -= 0.93 if len(c) <= 3 else 0.06
        if c.startswith('uten'):
            value -= 1.99
        if joins:
            if previous.endswith('l'):
                value -= 1.98
            if previous.endswith(('gl', 'sl')):
                value += 2.54
            if previous[-1] in 'aeiouy':
                value -= 0.78
            if previous.endswith('r'):
                value += 0.86
            if previous.endswith('s'):
                value -= 1.03
    if c.startswith('ud') and len(c) <= 4 and joins:
        if previous.endswith('l'):
            value -= 2.03
        if previous.endswith(('gl', 'sl')):
            value += 3.54
        if previous.endswith('r'):
            value += 1.10

    if c.startswith('olut') and len(c) <= 5:
        value -= 3.38
    if c.startswith('lut') and len(c) <= 4:
        value -= 1.72
    if c.startswith('eut') and len(c) <= 4:
        value -= 1.29
    if c.startswith('mut') and len(c) <= 3:
        value -= 0.50
    if c.startswith('tribut'):
        value -= 1.83
    if c.startswith('laut') or (joins and previous.endswith('l')
                                and c.startswith('aut')):
        value -= 3.15
    if joins and old.endswith('lieut') and c.startswith('en'):
        value -= 4.07

    clean = word.strip(' _\\')
    for stem, endings, amount in FAMILIES:
        spelling = clean
        if stem == 'strid' and spelling.startswith('a'):
            spelling = spelling[1:]  # Astrid shares the spelling pattern.
        if stem not in old and any(spelling == stem + e for e in endings):
            value += amount

    if previous.strip() in ('put', 'puts', 'putting'):
        if c == 'in':
            value += 3.57 if previous.strip() == 'putting' else 3.34
        elif c == 'forth':
            value += 3.02
        elif c in ('into', 'forward', 'on', 'out', 'to'):
            value += 0.70

    return (doc, s, word[-40:]), value

