            value = 4.4
        elif re.search(r'(?:supply|provision|receipt|provider)\s*$', tail):
            value = 1.6
    elif word == 'del':
        if token.strip()[0].isupper():
            value = 2.7
        else:
            value = 0.47 if token[:1].isspace() else 3.0
    elif not token[:1].isspace() and tail.endswith('d') and low.startswith('el'):
        value = 3.3 if low == 'el' else 1.3
    elif not token[:1].isspace() and tail.endswith('д') and low.startswith('ел'):
