The large responses occur on the first token of a document (or an initial
run of identical tokens). Numbers, punctuation, spatial qualifiers and
unspaced declaration keywords get negative estimates. Other initial words use
length, leading space, frequency and grammatical class as coarse amplitude
cues. Later tokens are zero except filesystem paths and named-import braces.
This captures context gating, not the exact amplitude of every initial token.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()


PREPOSITIONS = set("of in on at by for from to into onto with without over under "
                   "between through about after before".split())
PRONOUNS = set("i we you he she it they me us him her them".split())
MODALS = set("can could will would shall should may might must".split())
DECLARATIONS = set("package using def const class function module namespace "
                   "var let import".split())


def boundary(text):
    s = text.strip()
    if text.startswith('<|'):
        return -2.84
    if not s:
        return -0.3
    if s.isdecimal():
        return -1.5
