"""Closing-name detector (v5): names that close a block, tag or LaTeX environment."""
READS = ()
# block-closing keywords; at the start of a line they fire, inline they mostly don't
CLOSERS = {"#endif": -10.0, "fi": -10.0, "done": -6.0, "endif": -8.0, "esac": -8.0,
           "end": -4.0, "End": -4.0, "END": -4.0, "break": -4.0, "pass": -2.0, "continue": -1.5}
BLOCK_WORDS = {"If", "Sub", "Function", "Select", "Loop", "While", "With", "Try", "For",
               "Class", "Module", "Namespace", "Property", "Enum", "Type", "Using"}

def is_name(tok):
    s = tok.strip()
    return 0 < len(s) <= 20 and all(c.isalnum() or c in "-_.*" for c in s)

def line_start(toks):
    for tok in reversed(toks[-4:-1]):
        if "\n" in tok:
            return True
        if tok.strip():
            return False
    return False

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    c = cur.strip()
    prev = toks[-2] if len(toks) > 1 else ""
    state = carry or ""
    # inside a closing tag </name> or a LaTeX \end{name}: the name itself fires
    if state == "tag":
        if ">" in cur:
            return ("tag" if "</" in cur else ""), 0.0
        if is_name(cur):
            return "tag", -8.0
        return "", 0.0
    if state == "env":
        if "}" in cur:
            return "", 0.0
        if is_name(cur):
            return "env", -8.0
        return "", 0.0
    if "</" in cur:
        return "tag", 0.0
    if prev == "end" and cur == "{":
        return "env", -4.0
    if prev.strip() in ("End", "END") and c in BLOCK_WORDS:
        return "", -12.0
    if prev.strip().endswith("\\") and c in ("right", "end"):
        return "", -2.3 if c == "right" else -1.0
    if c == "workspace":
        return "", -2.4
    if c in CLOSERS and (line_start(toks) or c in ("#endif", "endif", "esac")):
        return "", CLOSERS[c]
    return "", 0.0

