"""Approximate a lateral-letter signal at a token boundary.

An l-initial fragment is positive after another l and negative after r,
with weaker negatives after other consonants. Short fragments stand out;
length, endings, capitalization and ordinary word frequency set their gain.
Related alphabetic scripts are transliterated, but Han/kana are not guessed.
Two separate rules cover document-initial 'Title:' and doubled interpuncts.
This deliberately leaves out token-specific amplitudes and other variation.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# Strength of the preceding consonant and its vowel-consonant ending.
CONSONANTS = {
    'l': 0.875, 'r': -0.758, 'n': -0.697, 'd': -0.573,
    't': -0.364, 's': -0.121, 'h': -0.122, 'g': -0.157,
    'b': -0.111, 'm': -0.135, 'v': -0.241, 'z': -0.281,
}
ENDINGS = {
    'ar': -0.464, 'er': -1.354, 'ir': -0.134,
    'or': -2.306, 'ur': -0.416, 'al': 0.745,
    'el': 0.224, 'il': 0.327, 'ol': 0.04,
    'ul': 0.345, 'ing': 0.105, 'ch': 0.059,
    'sh': -0.389, 'th': -0.319,
}

@lru_cache(maxsize=4096)
def fragment_gain(text):
    raw = text.lstrip('-')
    if not raw:
        return 0.0
    script = unicodedata.name(raw[0], '').split(' ')[0]
    if script not in ('LATIN', 'CYRILLIC', 'ARABIC', 'GREEK'):
        return 0.0
    letters = anyascii(raw).lower()
    if not letters.startswith('l'):
        return 0.0
    frequency = zipf_frequency(letters, 'en')
    gain = .463 + 1.573 / len(letters)
    gain -= .092 * max(0, len(letters) - 3)
    gain += .525 * letters.endswith('y')
    gain -= .498 * letters.endswith('r')
    gain -= .225 * letters.endswith('s')
    gain -= .284 * raw[0].isupper()
    gain -= .181 * max(0, frequency - 4)
    gain -= .525 * text.startswith('-')
    return max(0.0, gain)

@lru_cache(maxsize=4096)
def boundary_strength(previous):
    letters = anyascii(previous).lower()
    strength = CONSONANTS.get(letters[-1:], 0.0)
    strength += ENDINGS.get(letters[-2:], 0.0)
    if letters.endswith('ing'):
        strength += ENDINGS['ing']
    strength += .038 * (len(letters.strip()) == 1)
    # A final letter is less salient inside a long preceding token.
    return strength * min(1.0, 3.0 / max(1, len(letters.strip())))

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    value = -.002
    gain = fragment_gain(text)
    if gain:
        value = gain * boundary_strength(previous)
    if position == 1 and previous == 'Title' and text == ':':
        value = 10.39
    elif text == '··':
        value = 1.16
    return (doc, text, position + 1), float(value)

"""A lexical approximation of free choice, alternatives, and a few Han signals.

'Any' is strongest in possibility/ability contexts (especially 'be any',
'at any', etc.), weaker in existential contexts ('have/find any'), and
suppressed by recent negation. Two fading possibility memories also modify
'either', 'or', and related words. Small count + 'or' and the continuations
'any of', 'or more', and 'up to' receive phrase-specific responses.
Possessive favourites are negative; 'can/could always' is positive.

A separate lexical branch recognizes explosive/violent Han characters,
exposure 曝, and Korean 폭. It also handles their split UTF-8 encodings,
including incomplete byte prefixes shared with other characters. Chinese
choice and importance words have fixed negative responses. Everything else
is zero; document boundaries reset the state. These are approximate rules,
not a claim that all these responses share one meaning.
"""
import inflect

READS = ()
MODALS = {'can': 1.0, 'could': 0.8, 'may': 0.8, 'might': 0.3}
_numbers = inflect.engine()
SMALL_COUNTS = {_numbers.number_to_words(n) for n in range(1, 6)}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', "'s", '’s'}
CHARACTERS = {
    '爆': 5.4, '炮': 5.4, '砲': 5.4,  # explosion and cannon
    '暴': 6.5, '曝': 5.0, '폭': 10.0,  # violence, exposure, Korean explosion
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, 0.0, '', 0, b'')
    _, short, long, previous, negative, tail = carry
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = 0.0
    if word == 'any':
        slope = 5.0
        base = -0.8
        if previous in {'be', 'in', 'at', 'from'}:
            slope = 10.0
            base = -0.3 if previous == 'be' else -1.3
        elif previous in {'have', 'has', 'had', 'find', 'are', 'there', 'if'}:
            base, slope = -0.2, 2.0
        value = base - slope * short
        if previous == 'or':
            value = -3.0 - 2.0 * short
        if negative:
            value *= 0.15
    elif word == 'either':
        value = -0.3 - 3.8 * long
        if negative:
            value *= 0.25
    elif word == 'or':
        value = -0.05 - 1.8 * long
        if previous in SMALL_COUNTS:
            value -= 2.5 + 2.0 * long
        elif previous.isdigit() and len(previous) == 1:
            value -= 0.5 + 2.5 * long
        elif previous == 'singly':
            value -= 4.0
        if negative:
            value *= 0.4
    elif word in {'anyone', 'anybody', 'anytime'}:
        value = -0.8 - 3.0 * short
    elif word == 'anywhere':
        value = -5.7 if previous == 'from' else -0.8 - 3.0 * short
    elif word == 'anything':
        value = -0.15 - (9.0 if previous == 'be' else 3.0) * short
    elif word in {'whatever', 'whichever', 'arbitrary'}:
        value = -0.55 - 1.5 * short
    elif word in {'favorite', 'favourite'}:
        value = -3.0 if previous in POSSESSIVES else -2.0
        if previous == 'a':
            value = -0.5
        if word == 'favourite':
            value *= 1.3
    elif word in {'favorites', 'favourites'}:
        value = -0.6
    elif word == 'of' and previous == 'any':
        value = -0.75 - 0.6 * long
    elif word == 'more' and previous == 'or':
        value = -1.1 - 0.6 * long
    elif word == 'to' and previous == 'up':
        value = -0.05 - 2.0 * long
    elif word == 'always':
        value = 3.4 if previous in {'can', 'could'} else -0.15
    if raw and raw[0].isalpha() and previous[-1:].isalpha():
        value *= 0.3
    if raw.strip().istitle():
        value *= 0.5

    if raw in CHARACTERS:
        value = CHARACTERS[raw]
    elif raw in {'火爆', '暴力', '暴雨'}:
        value = 3.4
    elif raw == '任何':
        value = -2.4
    elif raw == '各种':
        value = -0.9
    elif raw in {'关键', '重点', '重要的'}:
        value = -1.6

    data = prefix.token_bytes[-1]
    joined = tail + data
    if '\ufffd' in raw:
        completed = joined.decode('utf-8', errors='ignore')[-1:]
        if completed in CHARACTERS and joined.endswith(completed.encode('utf-8')):
            value = max(7.0, CHARACTERS[completed])
        # The first two bytes can themselves be a token boundary.
        if any(joined.endswith(ch.encode('utf-8')[:2]) for ch in '暴炮'):
            value = 8.0

    strength = MODALS.get(word, 0.0)
    if word in {'able', 'capable', 'allowed', 'allows', 'permit', 'permits'}:
        strength = 0.7
    short = max(0.8 * short, strength)
    long = max(0.9 * long, strength)
    if word in {'not', "n't", 'n’t', 'never', 'without'}:
        negative = 6
    else:
        negative = max(0, negative - 1)
    return (doc, short, long, word, negative, joined[-3:]), float(value)

