CONNECTIVES = (
    "不过", "但是", "但", "然而", "其实", "所以", "那么", "因此", "同时", "于是", "而且",
    "此外", "另外", "现在", "最近", "这时", "这样", "然后", "接着", "首先", "其次", "总之",
    "可是", "虽然", "因而", "后来", "当时", "同样", "事实上", "一天", "因为", "如果", "若是",
)
TIME_END = set("此后时是前候時日来外上年中间里面")
YEAR_DASH = re.compile(r"(19|20)\d\d\D{0,2}\d{0,2}$")
CJK = re.compile(r"[\u4e00-\u9fff]")
