            value = -1.1
        else:
            value = 0.0
    elif len(tok) >= 2 and set(tok) == {"·"}:
        value = -0.9
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Closing-delimiter signal, strongest for square and curly brackets.

A brace after only indentation is weaker; a brace after a tab-separated
line number is stronger. Attached newlines, openers, and punctuation modulate
the signal. Ordinary parentheses alone are not a trigger. The carry keeps
the last 160 characters of the current line, resetting between documents.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    value = 0.003
    curly, square = text.count('}'), text.count(']')
    if not text.startswith('<|'):
        if curly:
            before = (line + text[:text.index('}')]).split('\n')[-1]
            value -= 1.10 + 0.54 * min(curly - 1, 2)
            if not before.strip():
                value += 0.48
            if re.fullmatch(r'\s*\d+\t\s*', before):
                value -= 0.48
            if '\n' in text:
                value += 0.35
            if ')' in text[text.index('}') + 1:]:
                value += 0.33
            if '{' in text:
                value += 0.63
        if square:
            value -= 1.06 + 0.05 * min(square - 1, 2)
            if '[' in text:
                value += 0.79
            if '.' in text:
                value += 0.55
            if ':' in text:
                value += 0.46
            if ',' in text:
                value += 0.16
            if text.startswith(' '):
                value -= 0.37
            if '\n' in text:
                value += 0.29
            if curly:
                value += 0.28
        if '>' in text and not any(c.isalnum() for c in text):
            value -= 0.30
            if text.startswith(' '):
                value += 0.24
            if '\n' in text:
                value -= 0.15
        if any(unicodedata.category(c) == 'Pe' and c not in '})]）' for c in text):
            value -= 0.35
        if '{' in text and not curly:
            value -= 0.04
        if text.isspace():
            value += 0.01
        if ')\\' in text:
            value += 0.22
    line = (line + text).split('\n')[-1][-160:]
    return (doc, line), value

programs.haiku:
"""Negative on closing square and curly brackets (], }) when they end a group:
about -0.9 after content and -0.6 when the bracket starts a line. Also negative on
the '.com' of 'github.com' (strongly), on '.com' elsewhere, on '>' tokens, and on
runs of middle dots '··'."""

READS = ()

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if "]" in tok or "}" in tok:
        return None, (-0.6 if prev.strip() == "" else -0.9)
    if tok == ".com":
        return None, (-2.2 if "github" in prev else -0.7)
    if tok == "··":
        return None, -1.3
    if tok.startswith(">"):
        return None, -0.5
    return None, 0.0

programs.sol:
"""Sparse spelling and formatting responses in an early MLP.

The main negative responses are the usual/unusual word family, User-Agent,
and U-A fragments at token boundaries (not arbitrary 'ua' inside words).
There is also a large response to the colon in document-initial 'Title:'.
Coefficients summarize training examples; other token-specific and
multilingual responses are left near zero.
"""
import unicodedata

READS = ()
POSSESSIVES = {'my', 'your', 'our', 'their', 'his', 'her', 'its'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, age = '', 0
    else:
        _, previous, age = carry
        age += 1
    word = token.strip().lower()
    prev = previous.lower()
    value = 0.208 if age == 0 else -0.003

    if age == 1 and previous == 'Title' and token == ':':
        value = -13.394
    elif prev.endswith('user') and word.lstrip('-_').startswith('agent'):
        value = -10.05 if prev.strip() == 'user' else -7.2
    elif word == 'useragent':
        value = -2.72
    elif word == 'usual':
        value = -6.98 + (2.1 if prev.strip() in POSSESSIVES else 0.0)
    elif word == 'usually':
        value = -2.65
    elif word == 'unusual':
        value = -4.27
    elif word == 'unusually':
        value = -3.15
    elif word == 'useful':
        value = -0.94
    elif word == 'usable':
        value = -1.84
    elif word == 'suitable':
        value = -1.58
    elif word == 'suitability':
        value = -0.38
    elif word == 'usage':
        value = -0.61
    else:
        if word.startswith('ua') and len(word) <= 5:
            value -= 0.33
        if word == 'ua':
            value -= 1.70
        # Split spellings such as Hu-am, su-as, Us-ual.
        if token and not token[0].isspace():
            first = unicodedata.normalize('NFD', token[0].lower())[0]
            if prev.endswith('u') and first == 'a':
                value -= 0.95
                if prev.endswith('su'):
                    value -= 2.91
                if word.startswith('am'):
                    value -= 1.70
            if prev.endswith('us') and word.startswith('ual'):
                value = -8.0
            # The same vowel succession in Cyrillic spelling.
            if prev.endswith('у') and first == 'а':
                value -= 2.7
    return (doc, token, age), float(value)

"""A response to separators after name-like text.

A standalone space following a comma is negative. Capitalized words in the
preceding phrase strengthen this response; numeric and lowercase text is weaker.
Newlines ending short, capitalized text near the start of a document are also
negative. Conversely, command-line option markers have a positive response.
Small adjustments cover quotes and nonbreaking spaces.
These are approximate text rules, not a token-identity lookup table.
"""
import re

READS = ()
COMMANDS = set(('cat grep rg head tail python python3 sed awk git ls find '
                'ssh ssh-keygen ssh-keyscan ssh-copy-id curl wget pip pytest '
                'npm cargo go node java javac docker sudo').split())


def comma_space(text, n, words):
    last = words[-1] if words else ''
    third = words[-3] if len(words) >= 3 else ''
    capitals = sum(w[:1].isupper() for w in words[-5:])
    return (-0.31 - 0.83 * last.istitle() - 0.19 * capitals
            - 0.28 * third.istitle() - 0.33 * (n < 32)
            - 0.69 * text.endswith('.,'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, n = '', 0
    else:
        _, text, n = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' ', ' -', ' --', ' &&') or ('\n' in token and not token.strip()):
        words = re.findall(r'[^\W_]+', text[-160:])
        last = words[-1] if words else ''
        capitals = sum(w[:1].isupper() for w in words[-5:])
        if token == ' ':
            if not text:
                value = -0.325
            elif text.endswith(','):
                value = comma_space(text, n, words)
            elif text.endswith((':', ';')):
                value = -0.1
        elif token in (' -', ' --'):
            command = re.search(r'([\w.-]+)$', text)
            if command and command[1].lower() in COMMANDS:
                value = 0.95
        elif token == ' &&':
            value = 0.34 if '/' in text[-100:] else 0.1
        else:
            line_words = re.findall(r'[^\W_]+', text.rsplit('\n', 1)[-1])
            gap = len(text) - text.rfind(',', 0, max(0, len(text) - 1))
            if n == 0 and token == '\n':
                value = 0.35
            elif n < 14:
                if last.istitle():
                    value = -0.87 if n < 8 else -0.42
                else:
                    value = -0.27 if gap < 36 else -0.04
            else:
                value = -0.01
                if capitals >= 3 and len(line_words) <= 4:
                    value = -0.11
                elif capitals <= 2 and len(line_words) > 4:
                    value = 0.035
    elif token == '\xa0':
        value = -0.1
    elif token in (' "', " '", ' `'):
        value = -0.06
    return (doc, (text + token)[-200:], n + 1), float(value)

programs.haiku:
"""Layer 1, MLP down-projection unit 3831 of Qwen3-1.7B.

Plain-terms summary, from its activations on training text:

1. Mostly a space right after a comma (", "). That is where the model is about to write a
   number, usually a year, in a reference or date ("Linnaeus, 1758", "Springer US, 2010",
   "March 5, 2010", "et al., 2001"). The unit goes negative there:
   - a comma glued to a period, as after an abbreviation ("Inc.,"): -2.0;
   - the token before the comma is a number (a list such as "(0, 0)"): -0.3;
   - a citation marker ("et al", "v.", "In") or a line with no digit yet: -1.5;
   - any other comma after a word: -0.8.
2. A hyphen that opens a command-line option ("grep -E", "head -100", "2>&1 | tail -50",
   "cat -n", "&& npm test -"): +0.7, when the line so far has a pipe, "&&" or a shell
   command word.
3. The first token of each document: -0.14.
Everywhere else the unit is close to zero.

The program keeps no state beyond the text of the current line and whether a new document
has started.
"""

import re

READS = ()

CITATION = re.compile(r"et al|\bv\.|\bIn\b")
SHELL_CMD = re.compile(
    r"\b(grep|head|tail|cat|find|ls|npm|pytest|python3?|git|sed|awk|cd|pip|make|go|"
    r"docker|curl|sort|wc|xargs|cp|rm|mkdir|echo|sudo|apt|yarn|node|cargo|bash|tar|rg)\b"
)


def line_so_far(token_strings):
    """Text of the current line before the newest token, back to the last newline."""
    parts = []
    for tok in reversed(token_strings[:-1]):
        if "\n" in tok or "<|endoftext|>" in tok:
            break
        parts.append(tok)
        if sum(len(p) for p in parts) > 150:
            break
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.14
    if cur == " " and prev.endswith(","):
        line = line_so_far(toks)
        before = toks[-3] if len(toks) > 2 else ""
        if prev == ".,":
            value = -2.0
        elif any(c.isdigit() for c in before):
            value = -0.3
        elif CITATION.search(line) or not any(c.isdigit() for c in line):
            value = -1.5
        else:
            value = -0.8
        return carry, value
    if cur in (" -", " --"):
        line = line_so_far(toks)
        if "|" in line or "&&" in line or SHELL_CMD.search(line):
            return carry, 0.7
    return carry, 0.0

programs.sol:
"""Approximate a lexical I/O signal and a negative English '... in' signal.

Recognize streams, I/O names, operations, parameter modes and IoT identifiers.
For space-prefixed 'in', progress/research/time expressions get strong negative
values; WordNet noun classes give weaker penalties. Code punctuation adjusts
some responses. Keep 200 characters of history, resetting for each document.
"""
import re
from functools import lru_cache
import wordnet

READS = ()


@lru_cache(maxsize=4096)
def before_in(word):
    bases = set(wordnet.base_forms(word)) | {word}
    if 'step' in bases:
        return -6.0 if word == 'step' else -3.0
    if 'course' in bases or 'factor' in bases:
        return -3.0
    if bases & {'point', 'phase', 'stage', 'intermediate'}:
        return -2.0
    if word == 'latest':
        return -6.0
    if word in {'early', 'earlier', 'late', 'later'}:
        return -2.7
    if wordnet.is_a(word, 'investigation'):
        return -3.0
    cats = wordnet.categories(word)
    broad = {'noun.act', 'noun.location', 'noun.artifact',
             'noun.communication', 'noun.cognition'}
    return (-0.04 - 0.08 * len(cats & broad)
            - 0.3 * ('noun.time' in cats)
            - 0.15 * ('noun.person' in cats)
            - 0.13 * ('noun.event' in cats))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lstrip('._/(-').lower()
    previous = re.search(r'[A-Za-z]+$', tail)
    prev = previous[0].lower() if previous else ''
    code = bool(re.search(r'[{};=]|::|```', tail[-150:]))
    value = 0.0
    if token == ' in':
        progress = r'\b(step forward|stepping stone|at (this|that|some) point)$'
        if re.search(progress, tail, re.I):
            value = -5.0
        elif tail.rstrip().endswith(':'):
            value = 2.4
        elif prev.endswith(('reader', 'stream')):
            value = 2.0
        else:
            value = before_in(prev) + 0.17 * code
    elif word in {'in', 'out'} and not token[0].isspace() and prev == 'std':
        value = 6.5
    elif raw == '/O' and tail.endswith('I'):
        value = 7.0
    elif re.search(r'(?:\b|[._/])(IoT|iot)$', tail + token):
        value = 3.5
    elif word == 'nio':  # Java's nonblocking I/O package
        value = 4.0
    elif word == 'ioexception':
        value = 6.0 if token[0].isspace() else 2.5
    elif word == 'ioerror':
        value = 1.0
    elif word == 'io' and raw.lstrip('._/(-') in {'io', 'IO'}:
        if re.search(r'(Bytes|String)$', tail):
            value = 8.5
        elif tail.endswith('Socket'):
            value = 4.8
        elif tail.endswith('::'):
            value = 9.0
        elif tail.endswith('::<'):
            value = 6.5
        elif token[0].isspace() or raw[0] in '._/(-' or not previous:
            value = 3.2 if raw.startswith('.') else 4.0
    elif word in {'input', 'output', '输入', '输出'}:
        value = 1.3 if raw[:1].isupper() or raw[:1] in '._' else 0.85
    elif re.fullmatch(r'(input|output)stream(reader|writer)?', word):
        value = 3.7
    elif word in {'stdin', 'stdout', 'ostream', 'istream'}:
        value = 1.3
    elif word in {'reader', 'writer'}:
        typed = re.search(
            r'(Binary|Buffered|InputStream|OutputStream|Xml|tab)$', tail
        )
        value = 5.5 if typed else (
            3.3 if code or (not token[0].isspace() and raw[:1].isupper())
            or raw[:1] in '._' else 0.1)
    elif word == 'readwrite' or (word == 'write' and prev == 'read'):
        value = 4.0
    elif (word in {'read', 'write'}
          and re.search(r'(Stream|analog|io::)$', tail)):
        value = 4.5
    elif word == 'out' and prev == 'in':
        value = 6.5 if re.search(r':\s*in$', tail) else 3.5
    elif word == 'out' and prev == 'read':
        value = 4.5
    elif word == 'out' and tail.rstrip().endswith(':'):
        value = 4.0
    elif word == 'out':
        argument = tail.rstrip().endswith((',', '('))
        value = 2.5 if code and argument else 0.15
    elif word in {'read', 'reading'}:
        value = 1.3 if code or raw[:1] in '._' else 0.1
    elif word in {'write', 'writing'}:
        value = 0.7 if code or raw[:1] in '._' else 0.1
    return (doc, (tail + token)[-200:]), value

"""Sparse surface-form detector with a document-initial spelling bias.

The largest positive responses are to the Chinese dou (斗/鬥) character,
weaving/drawing characters, stacking/folding forms, and a title label's colon.
Merged words are distinguished from isolated characters. Initial tokens have
an additional, coarse bias based on case, length and whitespace. A run of
identical initial tokens keeps that bias until the first different token.
Split UTF-8 endings also give negative responses for organ, healing and hair
characters, two hiragana syllables and circled Latin letters. These are
selective spelling rules, not a general detector of fighting or illness.
"""
import unicodedata
import regex

READS = ()


def initial_bias(s):
    word = s.strip()
    value = -0.036 * min(len(word), 12)
    if s[:1].isspace():
        value += 0.34
    if word[:1].isupper():
        value -= 0.29
    if word.islower():
        value -= 0.10
    if word.isdigit():
        value -= 0.08
    if word and all(unicodedata.category(c).startswith('P') for c in word):
        value -= 0.25
    if not s.isascii():
        value -= 0.34
    if regex.search(r'\p{Script=Han}', word):
        value += 0.33
    if any(c in '_\\/={}[]' for c in word):
        value -= 0.06
    if not word:
        value -= 0.61
    if s.startswith('<|'):
        value += 0.21
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    s = b.decode('utf-8', 'replace')
    if carry is None or carry[0] != doc:
        previous, initial_run, tail = b'', True, b''
    else:
        _, previous, initial_run, tail = carry
        initial_run = initial_run and b == previous

    title_label = (previous == b'Title' and carry is not None
                   and carry[0] == doc and carry[2])
    value = initial_bias(s) if initial_run else 0.0
    word = s.strip()
    prev = previous.decode('utf-8', 'replace')
    if word in ('斗', '鬥'):
        value = 5.7
        if prev.endswith(('战', '戰')):
            value = 0.8
        elif prev.endswith('料'):
            value = 4.5
        elif prev.endswith('械'):
            value = 3.5
    elif word in ('斗争', '奋斗'):
        value = 1.5
    elif word in ('织', '織'):
        value = 4.8
    elif word in ('绘', '繪', '纺织', '紡織'):
        value = 2.3
    elif word in ('叠', '疊'):
        value = 8.0
    elif word in ('折叠', '叠加', '折疊'):
        value = 2.1
    elif word == '袋':
        value = 2.4

    # UTF-8 fragments can finish a character in the newest token.
    if '\ufffd' in s:
        completed = (tail + b).decode('utf-8', 'replace')
        if completed.endswith(('継', '繰')):
            value = 2.1
        elif completed.endswith('疊'):
            value = 8.0
        elif completed.endswith(('臓', '臟')):  # Internal-organs character.
            value = -3.9
        elif completed.endswith(('癒', '瘉')):  # Healing character.
            value = -2.3
        elif completed.endswith(('髪', '髮')):  # Hair character.
            value = -1.1
        elif completed.endswith(('ん', 'げ')):
            value = -2.3
        elif unicodedata.name(completed[-1], '').startswith(
                'CIRCLED LATIN SMALL LETTER'):
            value = -2.8

    if word == '··':
        value = -0.78
    if initial_run and word == 'Title':
        value = 0.51
    if word == ':' and title_label:
        value = 2.77
    return (doc, b, initial_run, (tail + b)[-8:]), float(value)

"""A spelling-boundary response to TH, approximated by short rules.

Short E continuations tend positive; other vowels, especially I plus a
second vowel, tend negative. Short token fragments respond more than familiar
whole words. Case and nearby accented Latin text adjust TH-initial
fragments. English TH function words have simple grammatical-context
rules. Small document-start and repeated-punctuation offsets are included.
Lexical variation within these spelling classes is not modeled.
"""
import unicodedata as ud
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
FUNCTION_WORDS = set(
    'the then them there these those that than this their they thus'.split()
)
PRONOUNS = set('i you he she it we they'.split())
COPULAS = set('am is are was were be been being'.split())
PREPOSITIONS = set(
    'of to with for between on in from among by around about at'.split()
)
SPATIAL = set('before after behind below above beneath beside'.split())

@lru_cache(maxsize=65536)
def plain(s):
    return ''.join(c for c in ud.normalize('NFD', s.lower())
                   if not ud.combining(c)).replace('θ', 'th').replace('ث', 'th')

@lru_cache(maxsize=65536)
def frequency(s):
    return zipf_frequency(s.lower(), 'en')

def clip(x):
    return max(0., min(1., x))

def vowel(s):
    s = plain(s)
    if s.startswith('r'):
        s = s[1:]
    return s[0] if s and s[0] in 'aeiou' else 'other'

# TH-initial fragments: base, shortness, capital, marked vowel, recent accent.
TOKEN_RULES = {
    'a': (0.26, -0.72, -0.91, -0.57, -0.65),
    'e': (-0.01, 0.55, 0.02, 0, -0.34),
    'i': (0.11, -1.22, -0.54, 0.76, -2.25),
    'o': (-0.08, -0.26, -1.15, -1.25, -0.09),
    'u': (-0.22, 0.54, -0.18, -0.01, -1.22),
    'other': (0.05, -0.1, -0.65, -0.08, -0.68),
}

# Continuations: base, familiar prefix, long prefix, space before prefix,
# single letter, two letters, initial vowel pair, closed three-letter pair.
BOUNDARY_RULES = {
    'a': (-0.61, 0.54, 0.63, -0.74, -0.64, -0.18, -0.07, -0.05),
    'e': (1.32, -1.14, -1.18, -0.34, -0.06, 2.14, -0.64, 0.38),
    'i': (-0.65, -0.96, 1.72, 0.34, -3.73, -0.89, -0.98, -2.13),
    'o': (-1.95, -0.34, 1.71, -0.54, 0.61, 0.12, 0.19, -0.01),
    'u': (-2.34, 0.52, 1.03, -0.72, -0.75, 0.69, 0.36, 0.9),
}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    prev, recent = ('', '') if start else carry[1:]
    s = prefix.token_strings[-1]
    t = s.strip()
    lo, p = plain(t), plain(prev)
    capital = bool(t) and t[0].isupper()
    accented = any(ord(c)>127 and 'LATIN' in ud.name(c, '') for c in recent)
    value = 0.
    if start:
        value = -.11 if t.isalpha() else -.05
        if not t:
            value = -.44
        elif t.isdigit():
            value = .03
    if len(t)>=2 and len(set(t))==1 and t[0] in '·^':
        value -= .95
    if lo in FUNCTION_WORDS:
        after_word = bool(prev) and prev[-1].isalpha()
        previous_word = prev.strip().lower()
        if lo == 'then':
            if previous_word in {'since', 'until'}:
                adjustment = 1.5
            elif previous_word == 'because':
                adjustment = 1.2
            elif previous_word in COPULAS:
                adjustment = .4
            elif previous_word in {'but', 'so'}:
                adjustment = .37
            elif previous_word in PRONOUNS:
                adjustment = -.07
            elif previous_word == 'and':
                adjustment = 0.
            else:
                adjustment = .02 + .23*after_word
            value += adjustment + .10*(not s.startswith(' ')) - .06*capital
        elif lo == 'them':
            adjustment = .17 if previous_word in PREPOSITIONS else .02
            if previous_word in SPATIAL:
                adjustment = .65
            value += adjustment + .23*(not s.startswith(' ')) + .10*capital
        elif lo == 'there':
            value += (.35 if previous_word in {'from', 'in'} else .06) - .05*capital
        elif lo == 'than':
            value += .06 - .12*capital
        elif lo == 'these':
            value += -.05 - .09*capital
        elif lo == 'those':
            value -= .04
        elif lo == 'thus':
            value += -.09 + .08*capital
    elif lo.startswith('th'):
        tail = lo[2:]
        if not tail:
            value -= .34*s.startswith(' ')
            value -= 2.46*(accented and (s.startswith(' ') or capital))
        else:
            rarity = clip((5.3-frequency(t))/1.5)
            if tail.startswith('r'):
                rarity *= clip(4.-frequency(t))
            base, short, cap, mark, context = TOKEN_RULES[vowel(tail)]
            value += rarity*(base + short*max(0., (4.-len(tail))/3.)
                             + cap*capital + context*accented)
            value += mark*(t != ud.normalize('NFD', t))
    segment = None
    if p.endswith('th') and s and s[0].isalpha():
        segment, prior = s, prev.strip()
    elif p.endswith('t') and s.lower().startswith('h'):
        segment, prior = s[1:], prev.strip()+'h'
    if segment and vowel(segment) in BOUNDARY_RULES:
        base, known, long, space, one, two, pair, closed = BOUNDARY_RULES[vowel(segment)]
        n = len(segment)
        length_factor = max(.1, clip((8.-len(plain(prior)))/5.))
        shortness = clip((6.-n)/4.)
        familiar = clip((frequency(prior)-3.)/1.5) if len(prior)>3 else 0.
        vowel_pair = n>=2 and plain(segment)[1] in 'aeiou'
        value += length_factor*(shortness*(base + known*familiar
                  + long*(len(plain(prior))>3) + space*prev.startswith(' '))
                  + one*(n==1) + two*(n==2) + pair*vowel_pair
                  + closed*(vowel_pair and n==3))
    return (doc, s, (recent+s)[-40:]), float(value)

"""Approximate determiner-led nominal expressions, especially time periods.

A small weighted sum of dictionary word classes and spelling cues is conditioned
on the immediately preceding word. Calendar periods after 'the' or a possessive,
'two' after a determiner, and 'each' after a preposition get the largest boosts.
Initial words have a negative offset. This is not a full syntactic parser and
misses substantial word-specific variation. Initial uninterrupted runs of middle
dots or carriage returns receive separate negative formatting responses.
"""
from functools import lru_cache
import wordnet

READS = ()

PERIODS = {'day', 'year', 'night', 'week', 'month', 'season', 'semester'}
TIMES = {'time', 'morning', 'afternoon', 'evening', 'weekend', 'moment'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', "'s", '’s'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
PREPOSITIONS = {
    'of', 'for', 'in', 'on', 'at', 'by', 'with', 'from', 'to', 'about',
    'between', 'throughout', 'during', 'after', 'before', 'over', 'under',
    'through', 'into',
}

# Weights attach to interpretable word classes, not arbitrary token IDs.
BASE = {'day_or_year': .233, 'time_word': .186, 'each': .259}
AFTER_THE = {
    'ing': -.156, 'ly': -.304, 'period': 1.823, 'time_word': .328,
    'two': 1.389, 'noun.act': .073,
}
AFTER_POSSESSIVE = {
    'noun': .068, 'period': 1.384, 'time_word': 1.507, 'noun.act': .133,
}
AT_START = {
    'bias': -.259, 'space': -.212, 'ed': -.450,
    'noun.attribute': .258, 'noun.body': -.262,
}

@lru_cache(maxsize=65536)
def word_features(token):
    word = token.strip().lower()
    features = set(wordnet.categories(word))
    features.add('bias')
    if 'noun' in wordnet.parts_of_speech(word):
        features.add('noun')
    if token.startswith(' '):
        features.add('space')
    for suffix in ('ing', 'ed', 'ly'):
        if word.endswith(suffix):
            features.add(suffix)
    if word in PERIODS:
        features.add('period')
    if word in TIMES:
        features.add('time_word')
    if word in {'day', 'year'}:
        features.add('day_or_year')
    if word in {'each', 'two'}:
        features.add(word)
    return features


def weighted_sum(weights, features):
    return sum(value for name, value in weights.items() if name in features)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    # A document consisting initially of one repeated separator has a distinct
    # negative response; a middle dot embedded in ordinary text does not.
    initial_separator = token if start else carry[2]
    if token != initial_separator:
        initial_separator = None
    value = 0.0
    if initial_separator == '··':
        value = -3.123
    elif initial_separator == '\r':
        value = -4.330
    elif word.isalpha() and (start or token.startswith(' ')):
        features = word_features(token)
        value = weighted_sum(BASE, features)
        if start:
            weights = AT_START
        elif previous == 'the':
            weights = AFTER_THE
        elif previous in POSSESSIVES:
            weights = AFTER_POSSESSIVE
        elif previous in DEMONSTRATIVES:
            weights = {'two': .748}
        elif previous in PREPOSITIONS:
            weights = {'each': .535}
        else:
            weights = {}
        value += weighted_sum(weights, features)
    return (doc, word, initial_separator), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:3835: a "time / occasion word after the, your, each" detector.

What it responds to, in plain terms:
- A word from a short list of everyday time and occasion nouns, or a count word, right
  after a definite article, possessive, "each" or "all": "the day", "the week", "the
  season", "your night", "our time", "the two", "the post", "the choice", "the trip".
  Strongest for day, week, season, night and fix. Weaker for the same words elsewhere
  ("one day", "a lot of time").
- "each" is positive almost wherever it appears ("for each", "of each", "with each").
- After the same determiners, some adjectives and relational nouns push it negative:
  "the only", "the key", "the remaining", "the winning", "the central", "the result",
  "the heart", "the chance".
- "a", "one", "this", "that" and other words do not switch it on. Most nouns, including
  "period", "age" and "life", give about 0.
- The first token of each document (or of a packed row) is slightly negative.
- The filler token "··" (a run of middle dots) is strongly negative. This is a quirk of
  one repeated token, seen in one training row.

The weights are hand-set from the component's activations on training rows, and the word
lists are short concept lists, not a vocabulary. On eval rows this explains about 0.16 of
the variance (the lexical ceiling with a full word table is about 0.2 to 0.24). The
remaining variance is spread over many ordinary words with small activations.
"""

READS = ()

DETERMINERS = {"the", "your", "our", "my", "his", "her", "their", "its", "all", "each"}
TIME_NOUNS = {
    "day", "week", "weekend", "morning", "evening", "night", "moment", "season",
    "summer", "month", "year", "time", "occasion", "hour",
}
COUNT_WORDS = {"two", "three"}
EVENT_NOUNS = {
    "post", "fix", "choice", "purchase", "piece", "trip", "journey", "visit",
    "cut", "turn", "fold", "hook", "argument", "claim", "request", "point",
    "field", "case", "list", "site", "job", "work", "decision", "experience",
    "attempt", "lesson", "move", "shot",
}
ADJECTIVES_NEG = {
    "only", "remaining", "resulting", "winning", "central", "key", "crucial",
    "fundamental", "dominant", "public", "intended", "correct", "vital",
}
RELATIONAL_NEG = {
    "heart", "result", "luck", "chance", "audience", "location", "context",
    "figure", "partner", "opponent", "champion", "response", "effect",
    "meaning", "truth", "sum", "enemy",
}
DOC_START = -0.27
DOTS_FILLER = "··"
DOTS_FILLER_VALUE = -3.1


def _word(token_string):
    return token_string.strip().lower()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == DOTS_FILLER:
        return carry, DOTS_FILLER_VALUE
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    word = _word(token)
    if word == "each":
        return carry, 0.5
    after_det = _word(prefix.token_strings[-2]) in DETERMINERS
    if word in TIME_NOUNS:
        return carry, 1.2 if after_det else 0.14
    if word in COUNT_WORDS:
        return carry, 1.1 if after_det else 0.0
    if word in EVENT_NOUNS:
        return carry, 0.8 if after_det else 0.13
    if not after_det:
        return carry, 0.0
    if word in ADJECTIVES_NEG:
        return carry, -0.75
    if word in RELATIONAL_NEG:
        return carry, -0.37
    return carry, 0.0

programs.sol:
"""A boundary-sensitive spelling detector for kin/kind, not their meaning.

Short unspaced kin fragments receive the strongest negative values; kind
and related spellings are weaker. A twelve-character transliterated tail
recognizes split k+in and ki+n spellings. Selected other continuations of
k, notably it/ite/iv, get positive values. Cross-token tests skip East Asian
script tokens, and the tail resets at each document boundary.

This captures the main spelling response, not every token-specific or
start-of-document activation.
"""
from anyascii import anyascii
from functools import lru_cache
import re
import regex

READS = ()


@lru_cache(maxsize=32768)
def spelling(token):
    return anyascii(token).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    word = text.strip()
    bare = word.lstrip('._-/(')
    spaced = raw[:1].isspace()
    value = -0.002

    # Strength of a fragment contained in this token.
    if bare in ('kin', 'kins'):
        value = -4.7 if spaced else -7.9
        if raw.strip()[:1].isupper():
            value += 1.2
    elif bare == 'kind':
        value = -3.8 if spaced else -5.5
    elif bare == 'kinds':
        value = -1.9
    elif bare.startswith('kind'):
        value = -0.9
    elif bare == 'kid':
        value = -3.0 if raw.strip()[:1].isupper() else -0.5
    elif bare == 'kids':
        value = -0.6
    elif bare == 'king':
        value = -0.3 if spaced else -1.8
    elif bare in ('kite', 'kites'):
        value = 4.5
    elif bare == 'skin':
        value = -1.0
    elif bare == 'skins':
        value = -1.5 if spaced else -4.5
    elif re.search(r'kins?$', bare):
        value = -2.8 if len(bare) <= 4 else -1.1

    if not raw.isascii():
        value *= 0.55

    # Only a newly arriving, unspaced continuation can complete a fragment.
    can_continue = not text[:1].isspace() and not regex.search(
        r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]', raw
    )
    if can_continue:
        if tail.endswith('k'):
            if re.fullmatch(r'in(?:[aeio]s?|n|ds?|s|der|da|ned|et|ka)?', text):
                value = -3.5
                if text == 'in' or text == 'inn':
                    value = -5.5
                elif text in ('ins', 'ind', 'inds'):
                    value = -7.8
                elif text.startswith('ine'):
                    value = -1.8 if text.endswith('s') else -2.8
            elif raw.lower() == 'і':
                value = -5.7
            elif text.startswith('yn'):
                value = -4.3
            elif raw.startswith('ن'):
                value = -2.4
            elif text in ('it', 'ite', 'ites', 'iv'):
                value = 4.8
                if text == 'it':
                    value = 4.2 if tail.endswith('sk') else 1.5
                if text == 'iv':
                    value = 6.0 if raw.islower() else 2.5
                if not raw.isascii():
                    value *= 0.45
            elif text in ('ime', 'ial', 'ics'):
                value = 3.6
            elif text.startswith('ier'):
                value = 1.2
            elif raw in ('id', 'ids', 'ides'):
                value = -2.6
            elif text.startswith('il'):
                value = -0.8
        elif (tail.endswith(('ki', 'ky'))
              and text.startswith('n') and len(text) <= 3):
            value = -7.0
            if raw == 'н':
                value = -9.0
            elif len(text) > 1:
                value = -4.5
            if any('\u0600' <= ch <= '\u06ff' for ch in raw):
                value = -3.4

    return (doc, (tail + text)[-12:]), value

"""Sentence-closing punctuation gives a negative signal.

Question/exclamation marks are stronger than full stops. Full stops following
numbers are stronger too, unless they look like list labels or numeric/code
syntax. A newline fused into a full-stop token usually removes the signal.
Ellipses and tildes in Chinese text are treated as informal sentence endings.
First tokens get a modest negative baseline. The opening metadata label
'Title:' is a separate, strong trigger.
"""
import re
import regex

READS = ()
ABBREVIATIONS = set(('Mr Mrs Ms Dr Prof Sr Jr St Mt Fig Figs FIG FIGS Eq Eqs '
                     'cf vs al No Nos Jan Feb Mar Apr Jun Jul Aug Sep Sept '
                     'Oct Nov Dec').split())


def full_stop(history):
    word = re.search(r'\w+$', history)
    word = word[0] if word else ''
    recent = history[-32:]
    if history[-1:].isalpha():
        if word in ABBREVIATIONS:
            return -0.15
        return -0.4 if '.' in recent else -0.55
    number = re.search(r'\d+$', history)
    number = number[0] if number else ''
    line = history.rsplit('\n', 1)[-1]
    if re.fullmatch(r'\s*(?:[-*>]\s*)?\d+', line):
        return 0.06
    before = history[-len(number)-1:-len(number)] if number else ''
    if number and before in ("'", '"', '(', '{'):
        return -0.1
    if len(number) >= 2:
        letters = sum(c.isalpha() for c in history)
        return -0.75 if letters < 0.25 * len(history) else -1.3
    code_marks = sum(c in '{}[]();_\\/' for c in recent)
    if code_marks:
        return -1.3 if before in ('=', '+', '-') else -0.65
    return -0.8 if '.' in recent else -1.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, count = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    z = s.strip()
    value = -0.006
    if s == ':' and count == 1 and history == 'Title':
        value = -11.97
    elif z and not any(c.isalnum() for c in z):
        if any(c in z for c in '!?！？'):
            value = -1.5 if any(c in z for c in '!！') else -1.1
            if '\n' in s:
                value = -0.63
            if any(c in z for c in '([={:'):
                value = -0.01  # Logical negation and other code operators.
            if s.startswith(' ') and (not history.rsplit('\n', 1)[-1].strip()
                    or history.rstrip().endswith(('&&', '||', '='))):
                value = -0.01
        elif any(c in z for c in '.。．…'):
            if z == '.' and not s.startswith(' '):
                value = full_stop(history)
            else:
                value = -0.55
                if z.endswith('.') and len(z) > 1:
                    value = -0.75
                if s.startswith(' '):
                    value = -1.1
            if '\n' in s and not s.startswith(' '):
                value = 0.03
            if '...' in z or '…' in z:
                value = -0.7
            if z == '..':
                value = -0.2
            if s.startswith(' ') and '\n' in s:
                value = -0.8
            if z.endswith(','):
                value = 0.05  # An abbreviation followed by a comma.
        elif len(z) > 1 and set(z) == {'·'}:
            value = -0.56
        elif z and set(z) <= set('~～'):
            if regex.search(r'\p{Script=Han}', history[-32:]):
                value = -1.4
    if count == 0:
        value = -0.25 if s.islower() else -0.13
        if not any(c.isalnum() for c in s):
            value = -0.4
    return (doc, (history + s)[-160:], count + 1), value

"""Detect horizontal spacing at real or backslash-escaped line starts.

Short even-sized space tokens respond most; the usual 3, 7, 11, ...
code-indentation tokens respond little. Space widths unused for about 80
tokens respond more, especially following a colon. Recent widths respond less.
Other text is left at zero; lexical background variation is not modeled.
"""
READS = ()


def indentation(spaces, gap, colon):
    novel = gap > 80
    if spaces == 2:
        return (2.6 if colon else 1.8) if novel else 0.8
    if spaces % 2 == 0:
        if spaces == 4 and novel and colon:
            return 2.8
        if spaces <= 12:
            return 1.2 if novel else 0.55
        return 0.7 if novel else 0.18
    if spaces == 1:
        return (0.4 if novel else 0.12) + (0.3 if colon else 0.0)
    value = (0.25 if spaces <= 5 else 0.1) if novel else -0.06
    if spaces == 3 and colon:
        value += 0.5 if novel else 0.15
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        carry = (doc, 0, '', {})
    _, column, tail, seen = carry
    s = prefix.token_strings[-1]
    position = prefix.position
    value = 0.0
    if s and not s.strip(' \t'):
        spaces, tabs = s.count(' '), s.count('\t')
        gap = position - seen.get(s, position - 1000)
        if tail.endswith('\\n'):
            value = 0.31 if spaces == 1 else 0.78 if spaces <= 4 else 0.62
        elif tabs:
            value = 0.04 if column == 0 else -0.08
            if spaces and spaces % 4 == 0:
                value = 0.65
            elif spaces % 4 == 2:
                value = 0.35
            if fresh and spaces == 0:
                value = 3.2 / tabs ** 0.5
        elif column == 0:
            value = indentation(spaces, gap, tail.endswith(':\n'))
            if fresh and spaces == 2:
                value = 0.75
        elif spaces % 4 == 0:
            value = 0.1
        seen[s] = position
    if '\n' in s:
        column = len(s.rsplit('\n', 1)[1])
    else:
        column += len(s)
    tail = (tail + s)[-3:]
    return (doc, column, tail, seen), value
